css:
@keyframes dbi-spend-grow { from { transform: scaleY(0); } }
@keyframes dbi-spend-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dbi-spend-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbi-spend-arc { from { stroke-dasharray: 0 100; } }
@keyframes dbi-spend-draw { from { stroke-dashoffset: 1; } }

.dbi-spend {
  /* re-theme with these four */
  --dbi-spend-paper: oklch(0.972 0.012 84);
  --dbi-spend-ink: oklch(0.27 0.025 55);
  --dbi-spend-accent: oklch(0.57 0.15 40);
  --dbi-spend-good: oklch(0.55 0.1 152);
  /* model series */
  --dbi-spend-m1: oklch(0.52 0.14 38);
  --dbi-spend-m2: oklch(0.77 0.12 78);
  --dbi-spend-m3: oklch(0.56 0.075 200);
  --dbi-spend-m4: oklch(0.72 0.07 135);
  /* derived */
  --dbi-spend-card: color-mix(in oklch, var(--dbi-spend-paper), white 55%);
  --dbi-spend-sunk: color-mix(in oklch, var(--dbi-spend-paper), var(--dbi-spend-ink) 4%);
  --dbi-spend-line: color-mix(in oklch, var(--dbi-spend-ink) 11%, transparent);
  --dbi-spend-line-2: color-mix(in oklch, var(--dbi-spend-ink) 22%, transparent);
  --dbi-spend-muted: color-mix(in oklch, var(--dbi-spend-ink) 62%, var(--dbi-spend-paper));
  --dbi-spend-faint: color-mix(in oklch, var(--dbi-spend-ink) 42%, var(--dbi-spend-paper));
  --dbi-spend-tint: color-mix(in oklch, var(--dbi-spend-accent) 11%, var(--dbi-spend-paper));
  --dbi-spend-bad: color-mix(in oklch, var(--dbi-spend-accent), oklch(0.5 0.2 25) 55%);
  --dbi-spend-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dbi-spend-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.8%, 1.077 24.3%, 1.085 28%, 1.067 32.4%, 1.008 43.4%, 0.993 50.2%, 0.999 76.1%, 1);
  --dbi-spend-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbi-spend-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border: 1px solid var(--dbi-spend-line);
  border-radius: 14px;
  background: var(--dbi-spend-paper);
  color: var(--dbi-spend-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbi-spend-accent);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbi-spend-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & small { font-size: 11.5px; color: var(--dbi-spend-muted); text-wrap: pretty; }
  & svg { display: block; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & [hidden] { display: none !important; }

  .dbi-spend-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbi-spend-muted); }

  /* ---------- shell ---------- */
  .dbi-spend-app {
    display: grid;
    height: 100%;
    grid-template-columns: 188px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side top" "side main";
  }
  .dbi-spend-side {
    grid-area: side;
    display: flex; flex-direction: column; gap: 26px;
    padding: 18px 12px 16px;
    border-right: 1px solid var(--dbi-spend-line);
    background: var(--dbi-spend-sunk);
  }
  .dbi-spend-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbi-spend-brand svg { width: 28px; height: 28px; padding: 4px; border-radius: 8px; background: var(--dbi-spend-ink); color: var(--dbi-spend-paper); fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; }
  .dbi-spend-brand span { display: grid; line-height: 1.15; }
  .dbi-spend-brand b { font-weight: 700; letter-spacing: -0.01em; }
  .dbi-spend-brand small { font-size: 11px; }
  .dbi-spend-nav { display: grid; gap: 2px; }
  .dbi-spend-navbtn {
    width: 100%; display: flex; align-items: center; gap: 10px;
    padding: 8px 10px; border-radius: 8px;
    color: var(--dbi-spend-muted); font-weight: 550;
    transition: background-color 160ms var(--dbi-spend-ease), color 160ms var(--dbi-spend-ease);
  }
  .dbi-spend-navbtn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  .dbi-spend-navbtn:hover { background: color-mix(in oklch, var(--dbi-spend-ink) 5%, transparent); color: var(--dbi-spend-ink); }
  .dbi-spend-navbtn[aria-current="page"] { background: var(--dbi-spend-card); color: var(--dbi-spend-ink); box-shadow: 0 0 0 1px var(--dbi-spend-line), 0 1px 2px color-mix(in oklch, var(--dbi-spend-ink) 8%, transparent); }
  .dbi-spend-navbtn[aria-current="page"] svg { color: var(--dbi-spend-accent); }
  .dbi-spend-sidefoot { margin-top: auto; display: grid; gap: 6px; padding: 12px 8px 0; border-top: 1px solid var(--dbi-spend-line); }
  .dbi-spend-sidefoot b { font-weight: 600; font-variant-numeric: tabular-nums; }
  .dbi-spend-meter { display: block; height: 4px; border-radius: 4px; background: var(--dbi-spend-line); overflow: hidden; }
  .dbi-spend-meter i { display: block; height: 100%; width: 80%; background: var(--dbi-spend-accent); border-radius: inherit; transform-origin: left; animation: dbi-spend-wipe 900ms var(--dbi-spend-ease) 200ms both; }

  .dbi-spend-top {
    grid-area: top;
    display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 16px; flex-wrap: wrap;
    padding: 16px 20px 12px;
    border-bottom: 1px solid var(--dbi-spend-line);
  }
  .dbi-spend-title { display: grid; gap: 2px; }
  .dbi-spend-h { font-size: clamp(19px, 1.2rem + 0.6cqi, 26px); font-weight: 680; letter-spacing: -0.025em; line-height: 1.1; }
  .dbi-spend-tools { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  .dbi-spend-chip {
    display: inline-flex; align-items: center; gap: 6px;
    height: 30px; padding: 0 8px 0 12px; border-radius: 99px;
    background: var(--dbi-spend-tint); color: color-mix(in oklch, var(--dbi-spend-accent), var(--dbi-spend-ink) 35%);
    font-weight: 600; font-size: 12px;
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbi-spend-accent) 30%, transparent);
    transition: scale 300ms var(--dbi-spend-spring), opacity 200ms;
    @starting-style { scale: 0.85; opacity: 0; }
  }
  .dbi-spend-chip svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dbi-spend-chip:hover { background: color-mix(in oklch, var(--dbi-spend-accent) 18%, var(--dbi-spend-paper)); }

  .dbi-spend-seg {
    display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px;
    background: var(--dbi-spend-sunk); box-shadow: inset 0 0 0 1px var(--dbi-spend-line);
  }
  .dbi-spend-seg button {
    height: 26px; padding: 0 11px; border-radius: 7px;
    font-size: 12px; font-weight: 600; color: var(--dbi-spend-muted); font-variant-numeric: tabular-nums;
    transition: background-color 180ms var(--dbi-spend-ease), color 180ms var(--dbi-spend-ease), box-shadow 180ms;
  }
  .dbi-spend-seg button:hover { color: var(--dbi-spend-ink); }
  .dbi-spend-seg button[aria-checked="true"] { background: var(--dbi-spend-card); color: var(--dbi-spend-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbi-spend-ink) 14%, transparent), 0 0 0 1px var(--dbi-spend-line); }

  .dbi-spend-main {
    grid-area: main; min-height: 0; overflow: auto; padding: 16px 20px 20px;
    scrollbar-width: thin; scrollbar-color: var(--dbi-spend-line-2) transparent;
  }
  .dbi-spend-view { display: grid; gap: 14px; align-content: start; }

  /* ---------- panels ---------- */
  .dbi-spend-panel {
    min-width: 0;
    background: var(--dbi-spend-card); border-radius: 12px;
    box-shadow: 0 0 0 1px var(--dbi-spend-line), 0 1px 2px color-mix(in oklch, var(--dbi-spend-ink) 5%, transparent);
    display: flex; flex-direction: column;
  }
  .dbi-spend-ph { display: flex; align-items: center; gap: 10px 14px; flex-wrap: wrap; padding: 12px 14px 10px; }
  .dbi-spend-ph h3 { font-size: 13.5px; font-weight: 650; letter-spacing: -0.01em; margin-right: auto; }
  .dbi-spend-hint { color: var(--dbi-spend-faint); }
  .dbi-spend-scroll { overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbi-spend-line-2) transparent; }

  /* ---------- KPIs ---------- */
  .dbi-spend-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--dbi-spend-line); box-shadow: 0 0 0 1px var(--dbi-spend-line); }
  .dbi-spend-kpi { display: grid; gap: 3px; padding: 12px 14px 12px; background: var(--dbi-spend-card); }
  .dbi-spend-kpi > * { animation: dbi-spend-rise 600ms var(--dbi-spend-ease) both; animation-delay: calc(var(--i) * 60ms); }
  .dbi-spend-kpi output { font-size: clamp(19px, 0.9rem + 1cqi, 25px); font-weight: 650; letter-spacing: -0.03em; line-height: 1.15; font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbi-spend-kpi small { font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbi-spend-kpi small b { font-weight: 650; }
  .dbi-spend-up { color: var(--dbi-spend-bad); }
  .dbi-spend-down { color: var(--dbi-spend-good); }

  /* ---------- legend ---------- */
  .dbi-spend-legend { display: flex; gap: 4px; flex-wrap: wrap; }
  .dbi-spend-lg {
    display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px 0 7px; border-radius: 7px;
    font: 500 11.5px/1 var(--dbi-spend-mono); color: var(--dbi-spend-ink);
    transition: opacity 160ms, background-color 160ms;
  }
  .dbi-spend-lg i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); transition: scale 260ms var(--dbi-spend-spring); }
  .dbi-spend-lg:hover { background: color-mix(in oklch, var(--dbi-spend-ink) 5%, transparent); }
  .dbi-spend-lg[aria-pressed="false"] { opacity: 0.45; }
  .dbi-spend-lg[aria-pressed="false"] i { scale: 0.6; background: transparent; box-shadow: inset 0 0 0 1.5px var(--c); }

  /* ---------- chart ---------- */
  .dbi-spend-chart, .dbi-spend-burn { position: relative; height: 252px; margin: 0 8px 10px 4px; outline-offset: -2px; touch-action: pan-y; }
  .dbi-spend-chart svg, .dbi-spend-burn svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbi-spend-grid { stroke: var(--dbi-spend-line); stroke-width: 1; shape-rendering: crispEdges; }
  .dbi-spend-base { stroke: var(--dbi-spend-line-2); }
  .dbi-spend-ytick, .dbi-spend-xtick { font: 10.5px var(--dbi-spend-mono); fill: var(--dbi-spend-faint); font-variant-numeric: tabular-nums; }
  .dbi-spend-ytick { text-anchor: end; }
  .dbi-spend-xtick { text-anchor: middle; }
  .dbi-spend-cross { fill: color-mix(in oklch, var(--dbi-spend-ink) 6%, transparent); transition: opacity 120ms; }
  .dbi-spend-col { transform-box: fill-box; transform-origin: 50% 100%; transition: opacity 160ms var(--dbi-spend-ease); }
  .dbi-spend-col rect { shape-rendering: crispEdges; }
  .dbi-spend-marks.dbi-spend-dim .dbi-spend-col:not(.dbi-spend-hot) { opacity: 0.38; }
  .dbi-spend-anim .dbi-spend-col { animation: dbi-spend-grow 680ms var(--dbi-spend-spring) both; animation-delay: calc(var(--i) * 540ms / var(--n)); }
  .dbi-spend-anim.dbi-spend-areas, .dbi-spend-anim .dbi-spend-burnline { animation: dbi-spend-wipe 900ms var(--dbi-spend-ease) both; }
  .dbi-spend-area { stroke: var(--dbi-spend-card); stroke-width: 1; stroke-linejoin: round; }
  .dbi-spend-hotline { stroke: var(--dbi-spend-ink); stroke-width: 1; stroke-dasharray: 2 3; }

  .dbi-spend-tip {
    position: absolute; top: 0; left: 0; z-index: 3; pointer-events: none;
    min-width: 176px; padding: 9px 10px 8px; border-radius: 10px;
    background: color-mix(in oklch, var(--dbi-spend-ink), black 20%); color: var(--dbi-spend-paper);
    font-size: 11.5px; box-shadow: 0 8px 24px color-mix(in oklch, var(--dbi-spend-ink) 28%, transparent);
    opacity: 0; transform: translateY(4px); transition: opacity 140ms var(--dbi-spend-ease), transform 200ms var(--dbi-spend-ease);
  }
  .dbi-spend-tip.dbi-spend-on { opacity: 1; transform: none; }
  .dbi-spend-tip header { font-weight: 650; margin-bottom: 6px; letter-spacing: 0.01em; }
  .dbi-spend-tip li, .dbi-spend-tip footer { display: flex; align-items: center; gap: 7px; font-variant-numeric: tabular-nums; padding: 1px 0; }
  .dbi-spend-tip li i { width: 8px; height: 8px; border-radius: 2px; flex: none; }
  .dbi-spend-tip li span { font-family: var(--dbi-spend-mono); font-size: 11px; opacity: 0.85; }
  .dbi-spend-tip b { margin-left: auto; font-weight: 600; font-family: var(--dbi-spend-mono); }
  .dbi-spend-tip footer { margin-top: 5px; padding-top: 6px; border-top: 1px solid color-mix(in oklch, var(--dbi-spend-paper) 20%, transparent); font-weight: 650; }

  /* ---------- tables ---------- */
  .dbi-spend-table { width: 100%; min-width: 520px; border-collapse: collapse; font-variant-numeric: tabular-nums; }
  .dbi-spend-table th, .dbi-spend-table td { padding: 8px 14px; text-align: right; white-space: nowrap; }
  .dbi-spend-table :is(th, td):first-child { text-align: left; }
  .dbi-spend-table thead th { position: sticky; top: 0; z-index: 1; background: var(--dbi-spend-card); font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbi-spend-muted); border-bottom: 1px solid var(--dbi-spend-line); }
  .dbi-spend-table thead button { letter-spacing: inherit; text-transform: inherit; font-weight: inherit; display: inline-flex; align-items: center; gap: 4px; }
  .dbi-spend-table thead button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; border-top-color: currentColor; translate: 0 2px; opacity: 0; transition: opacity 150ms, rotate 220ms var(--dbi-spend-ease); }
  .dbi-spend-table th[aria-sort="descending"] button, .dbi-spend-table th[aria-sort="ascending"] button { color: var(--dbi-spend-ink); }
  .dbi-spend-table th[aria-sort="descending"] button::after { opacity: 1; }
  .dbi-spend-table th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; translate: 0 -2px; }
  .dbi-spend-table td { font-family: var(--dbi-spend-mono); font-size: 12px; }
  .dbi-spend-table tbody tr { border-top: 1px solid var(--dbi-spend-line); animation: dbi-spend-rise 460ms var(--dbi-spend-ease) both; animation-delay: calc(var(--i) * 40ms); }
  .dbi-spend-table tbody th { font-weight: 600; }
  .dbi-spend-table tbody th small { display: block; font-weight: 400; }
  .dbi-spend-table tfoot td, .dbi-spend-table tfoot th { border-top: 1px solid var(--dbi-spend-line-2); font-weight: 650; }
  .dbi-spend-teams tbody tr { cursor: pointer; transition: background-color 140ms; }
  .dbi-spend-teams tbody tr:hover { background: color-mix(in oklch, var(--dbi-spend-ink) 3%, transparent); }
  .dbi-spend-teams tbody tr[aria-selected="true"] { background: var(--dbi-spend-tint); box-shadow: inset 3px 0 0 var(--dbi-spend-accent); }
  .dbi-spend-teams tbody tr:focus-visible { outline-offset: -2px; border-radius: 0; }
  .dbi-spend-teams:has(tr[aria-selected="true"]) tbody tr:not([aria-selected="true"]) { color: var(--dbi-spend-muted); }
  .dbi-spend-share { display: inline-block; vertical-align: middle; width: 72px; height: 6px; margin-right: 8px; border-radius: 6px; background: var(--dbi-spend-line); overflow: hidden; }
  .dbi-spend-share i { display: block; height: 100%; width: var(--w); background: var(--dbi-spend-accent); border-radius: inherit; transform-origin: left; animation: dbi-spend-wipe 700ms var(--dbi-spend-ease) both; animation-delay: calc(var(--i, 0) * 40ms + 120ms); }
  .dbi-spend-sw { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 8px; vertical-align: 0; }

  /* ---------- models ---------- */
  .dbi-spend-mgrid { display: grid; grid-template-columns: minmax(220px, 0.75fr) minmax(0, 2fr); gap: 14px; align-items: stretch; }
  .dbi-spend-models :is(th, td) { padding-inline: 10px; }
  .dbi-spend-unitpanel { grid-column: 1 / -1; }
  .dbi-spend-units { display: grid; padding: 0 14px 12px; }
  .dbi-spend-units li {
    display: grid; grid-template-columns: 150px 190px minmax(0, 1fr) 76px; align-items: center; gap: 6px 16px; padding: 9px 0;
    font-variant-numeric: tabular-nums; animation: dbi-spend-rise 500ms var(--dbi-spend-ease) both; animation-delay: calc(var(--i) * 50ms);
  }
  .dbi-spend-units li + li { border-top: 1px solid var(--dbi-spend-line); }
  .dbi-spend-units .dbi-spend-uname { font: 600 12px var(--dbi-spend-mono); }
  .dbi-spend-units .dbi-spend-unum { font: 11.5px var(--dbi-spend-mono); color: var(--dbi-spend-muted); }
  .dbi-spend-units b { font: 650 12.5px var(--dbi-spend-mono); text-align: right; }
  .dbi-spend-ubar { height: 10px; border-radius: 3px; background: var(--dbi-spend-sunk); overflow: hidden; }
  .dbi-spend-ubar i { display: block; height: 100%; width: var(--w); border-radius: inherit; animation: dbi-spend-wipe 800ms var(--dbi-spend-ease) both; animation-delay: calc(var(--i) * 60ms + 150ms); }
  .dbi-spend-donut { position: relative; width: min(220px, 100%); aspect-ratio: 1; margin: 6px auto 18px; }
  .dbi-spend-donut svg { width: 100%; height: 100%; rotate: -90deg; overflow: visible; }
  .dbi-spend-dseg { fill: none; stroke-width: 22; cursor: pointer; transition: stroke-width 260ms var(--dbi-spend-spring), opacity 200ms; animation: dbi-spend-arc 900ms var(--dbi-spend-ease) both; animation-delay: calc(var(--i) * 90ms); }
  .dbi-spend-donut:has(.dbi-spend-dseg:hover) .dbi-spend-dseg:not(:hover) { opacity: 0.4; }
  .dbi-spend-dseg:hover, .dbi-spend-dseg.dbi-spend-hot { stroke-width: 28; }
  .dbi-spend-dtrack { fill: none; stroke: var(--dbi-spend-line); stroke-width: 22; }
  .dbi-spend-dcenter { position: absolute; inset: 0; display: grid; place-content: center; text-align: center; gap: 2px; pointer-events: none; }
  .dbi-spend-dcenter b { font-size: 22px; font-weight: 680; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
  .dbi-spend-models tbody tr { transition: background-color 140ms; }
  .dbi-spend-models tbody tr:hover, .dbi-spend-models tbody tr.dbi-spend-hot { background: color-mix(in oklch, var(--dbi-spend-ink) 4%, transparent); }
  .dbi-spend-models tbody th { font-family: var(--dbi-spend-mono); font-size: 12px; font-weight: 600; }

  /* ---------- budgets ---------- */
  .dbi-spend-bgrid { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: 14px; align-items: stretch; }
  .dbi-spend-burnpanel .dbi-spend-burn { flex: 1; height: auto; min-height: 260px; }
  .dbi-spend-blist { display: grid; padding: 0 6px 8px; }
  .dbi-spend-brow {
    display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 12px; padding: 10px 10px 12px; border-radius: 10px; cursor: pointer;
    animation: dbi-spend-rise 500ms var(--dbi-spend-ease) both; animation-delay: calc(var(--i) * 50ms);
    transition: background-color 150ms;
  }
  .dbi-spend-brow + .dbi-spend-brow { box-shadow: 0 -1px 0 var(--dbi-spend-line); }
  .dbi-spend-brow:hover { background: color-mix(in oklch, var(--dbi-spend-ink) 3%, transparent); }
  .dbi-spend-brow[aria-selected="true"] { background: var(--dbi-spend-tint); box-shadow: none; }
  .dbi-spend-brow b { font-weight: 620; }
  .dbi-spend-brow .dbi-spend-nums { font: 11.5px var(--dbi-spend-mono); color: var(--dbi-spend-muted); text-align: right; font-variant-numeric: tabular-nums; }
