const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------- seeded usage records: day x team x model -> [requests, in, out, cents] ---------- */
let seed = 0x1a2b3c;
const rand = () => {
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const MODELS = [
  { id: 'atlas-large', pin: 3, pout: 15 },
  { id: 'nimbus-mini', pin: 0.3, pout: 1.2 },
  { id: 'cirrus-code', pin: 1.1, pout: 4.4 },
  { id: 'strata-embed', pin: 0.05, pout: 0 }
];
// [requests per weekday, avg input tokens, avg output tokens] for each model
const TEAMS = [
  { id: 'support', name: 'Support Copilot', lead: 'Maren Okafor', wk: 0.82, budget: 1.14, use: [[16800, 2400, 380], [72000, 900, 120], null, [88000, 60, 0]] },
  { id: 'search', name: 'Search & Answers', lead: 'Teo Lindqvist', wk: 0.7, budget: 1.2, use: [[3600, 2000, 300], [120000, 1500, 200], null, [240000, 40, 0]] },
  { id: 'platform', name: 'Platform Evals', lead: 'Ines Carvalho', wk: 0.35, budget: 1.12, use: [[10000, 3000, 500], [32000, 1100, 150], [12000, 1800, 400], null] },
  { id: 'research', name: 'Applied Research', lead: 'Dev Raman', wk: 0.45, budget: 1.06, use: [[3200, 6000, 1200], null, [18000, 2200, 700], [6000, 300, 0]] },
  { id: 'growth', name: 'Growth Studio', lead: 'Priya Nandakumar', wk: 0.6, budget: 1.1, use: [[4800, 1800, 900], [24000, 700, 250], null, null] }
];
const DAYS = 180, DAY = 864e5, END = Date.UTC(2026, 8, 24);
const dates = Array.from({ length: DAYS }, (_, d) => new Date(END - (DAYS - 1 - d) * DAY));
const data = dates.map((dt, d) => {
  const dow = dt.getUTCDay(), weekend = dow === 0 || dow === 6;
  const trend = 0.8 + 0.2 * (d / (DAYS - 1));
  const sep = dt.getUTCMonth() === 8 ? dt.getUTCDate() : 0;
  return TEAMS.map(t => t.use.map((u, m) => {
    if (!u) return [0, 0, 0, 0];
    let f = trend * (weekend ? t.wk : 1) * (0.9 + rand() * 0.2);
    if (t.id === 'growth' && sep >= 9 && sep <= 13) f *= 2.4;       // launch campaign
    if (t.id === 'platform' && m === 0 && dow === 1) f *= 1.7;      // Monday regression suite
    const r = Math.round(u[0] * f);
    const i = Math.round(r * u[1] * (0.95 + rand() * 0.1));
    const o = Math.round(r * u[2] * (0.95 + rand() * 0.1));
    return [r, i, o, Math.round((i * MODELS[m].pin + o * MODELS[m].pout) / 1e4)];
  }));
});
const ALL = new Set(MODELS.map((_, m) => m));

function agg(from, to, team, models) {
  const A = { r: 0, i: 0, o: 0, c: 0, model: MODELS.map(() => [0, 0, 0, 0]), team: TEAMS.map(() => [0, 0, 0, 0]), day: [] };
  for (let d = from; d <= to; d++) {
    const row = MODELS.map(() => 0);
    for (let t = 0; t < TEAMS.length; t++) {
      if (team != null && team !== t) continue;
      for (let m = 0; m < MODELS.length; m++) {
        if (!models.has(m)) continue;
        const v = data[d][t][m], a = A.model[m], b = A.team[t];
        A.r += v[0]; A.i += v[1]; A.o += v[2]; A.c += v[3];
        for (let k = 0; k < 4; k++) { a[k] += v[k]; b[k] += v[k]; }
        row[m] += v[3];
      }
    }
    A.day.push(row);
  }
  return A;
}

/* ---------- formatting ---------- */
const nf0 = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const nf2 = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cmp = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 });
const usd = c => '$' + nf2.format(c / 100);
const usd0 = c => '$' + nf0.format(Math.round(c / 100));
const usdAxis = c => c === 0 ? '$0' : '$' + cmp.format(c / 100);
const pct = (x, d = 1) => (x * 100).toFixed(d) + '%';
const dShort = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const dLong = new Intl.DateTimeFormat('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' });
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
function niceScale(max, ticks) {
  const raw = max / ticks, mag = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / mag;
  const step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * mag;
  return { step, top: Math.ceil(max / step) * step };
}

/* ---------- state ---------- */
const st = { view: 'overview', range: 30, mode: 'daily', team: null, models: new Set(ALL), sort: { key: 'spend', dir: -1 }, bteam: null, hover: -1, bhover: -1 };
const chart = $('.dbi-spend-chart'), svg = $('svg', chart), tip = $('.dbi-spend-tip', chart);
const burn = $('.dbi-spend-burn'), bsvg = $('svg', burn), btip = $('.dbi-spend-tip', burn);
const tbody = $('.dbi-spend-teams tbody'), tfoot = $('.dbi-spend-teams tfoot');
const chip = $('.dbi-spend-chip');

function vt(fn) {
  if (!reduce && document.startViewTransition) {
    try {
      const t = document.startViewTransition(fn);
      t.ready.catch(() => {}); t.finished.catch(() => {});
      return;
    } catch (e) { /* fall through */ }
  }
  fn();
}

function tween(el, to, fmt) {
  const from = el._v || to.map(() => 0), t0 = performance.now();
  el._v = to; el._t = t0;
  if (reduce) { el.textContent = fmt(...to); return; }
  const step = now => {
    if (!root.isConnected) return;
    if (el._t !== t0) return;
    const p = Math.min(1, (now - t0) / 720), e = 1 - Math.pow(1 - p, 4);
    el.textContent = fmt(...to.map((v, k) => from[k] + (v - from[k]) * e));
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
function delta(el, cur, prev, costLike) {
  if (!prev) { el.textContent = 'no prior data'; return; }
  const d = (cur - prev) / prev, cls = !costLike ? '' : d > 0 ? 'dbi-spend-up' : 'dbi-spend-down';
  el.innerHTML = `<b class="${cls}">${d >= 0 ? '+' : '−'}${pct(Math.abs(d))}</b> vs prior ${st.range} days`;
}

/* ---------- overview ---------- */
function renderKpis() {
  const n = st.range, cur = agg(DAYS - n, DAYS - 1, st.team, st.models), prev = agg(DAYS - 2 * n, DAYS - n - 1, st.team, st.models);
  const cpk = cur.r ? cur.c / cur.r * 1000 : 0, pcpk = prev.r ? prev.c / prev.r * 1000 : 0;
  tween($('[data-k="cost"]'), [cur.c], usd0);
  tween($('[data-k="tok"]'), [cur.i, cur.o], (a, b) => cmp.format(a) + ' / ' + cmp.format(b));
  tween($('[data-k="req"]'), [cur.r], v => nf0.format(v));
  tween($('[data-k="cpk"]'), [cpk], usd);
  delta($('[data-d="cost"]'), cur.c, prev.c, true);
  delta($('[data-d="tok"]'), cur.i + cur.o, prev.i + prev.o, false);
  delta($('[data-d="req"]'), cur.r, prev.r, false);
  delta($('[data-d="cpk"]'), cpk, pcpk, true);
}

function renderLegend() {
  $('.dbi-spend-legend').innerHTML = MODELS.map((M, m) =>
    `<button class="dbi-spend-lg" data-m="${m}" aria-pressed="${st.models.has(m)}" style="--c:var(--dbi-spend-m${m + 1})"><i></i>${M.id}</button>`).join('');
}

let geo = null;
function drawChart(animate) {
  const w = chart.clientWidth, h = chart.clientHeight;
  if (!w || !h) return;
  const n = st.range, from = DAYS - n, A = agg(from, DAYS - 1, st.team, st.models);
  let series = A.day;
  if (st.mode === 'cumulative') {
    const run = MODELS.map(() => 0);
    series = A.day.map(r => r.map((v, m) => (run[m] += v)));
  }
  const totals = series.map(r => r.reduce((a, b) => a + b, 0));
  const { top, step } = niceScale(Math.max(1, ...totals), 5);
  const L = 50, R = 6, T = 10, B = 24, iw = w - L - R, ih = h - T - B, bw = iw / n;
  const y = v => T + ih - (v / top) * ih;
  let g = '';
  for (let v = 0; v <= top + 1e-6; v += step) {
    g += `<line class="dbi-spend-grid${v === 0 ? ' dbi-spend-base' : ''}" x1="${L}" x2="${w - R}" y1="${y(v)}" y2="${y(v)}"/><text class="dbi-spend-ytick" x="${L - 8}" y="${y(v)}" dy="0.33em">${usdAxis(v)}</text>`;
  }
  const every = n <= 7 ? 1 : n <= 30 ? 5 : 15;
  for (let k = n - 1; k >= 0; k -= every) {
    g += `<text class="dbi-spend-xtick" x="${L + bw * (k + 0.5)}" y="${h - 6}">${dShort.format(dates[from + k])}</text>`;
  }
  let marks = '';
  if (st.mode === 'daily') {
    const gap = Math.max(1, bw * (n > 60 ? 0.22 : 0.3));
    for (let k = 0; k < n; k++) {
      let acc = 0, segs = '';
      for (let m = 0; m < MODELS.length; m++) {
        const v = series[k][m];
        if (!v) continue;
        const y0 = y(acc), y1 = y(acc + v); acc += v;
        segs += `<rect x="${(L + bw * k + gap / 2).toFixed(2)}" y="${y1.toFixed(2)}" width="${Math.max(0.6, bw - gap).toFixed(2)}" height="${Math.max(0, y0 - y1).toFixed(2)}" fill="var(--dbi-spend-m${m + 1})"/>`;
      }
      marks += `<g class="dbi-spend-col" data-k="${k}" style="--i:${k}">${segs}</g>`;
    }
  } else {
    let lower = series.map(() => 0);
    for (let m = 0; m < MODELS.length; m++) {
      if (!st.models.has(m)) continue;
      const upper = series.map((r, k) => lower[k] + r[m]);
      const xs = k => (L + bw * (k + 0.5)).toFixed(2);
      const fwd = upper.map((v, k) => xs(k) + ',' + y(v).toFixed(2));
      const back = lower.map((v, k) => xs(k) + ',' + y(v).toFixed(2)).reverse();
      marks += `<path class="dbi-spend-area" d="M${fwd.join('L')}L${back.join('L')}Z" fill="var(--dbi-spend-m${m + 1})"/>`;
      lower = upper;
    }
    marks = `<g class="dbi-spend-areas${animate && !reduce ? ' dbi-spend-anim' : ''}">${marks}</g>`;
  }
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  svg.innerHTML = g + `<rect class="dbi-spend-cross" x="0" y="${T}" width="${bw}" height="${ih}" opacity="0"/>` +
    `<g class="dbi-spend-marks${animate && !reduce && st.mode === 'daily' ? ' dbi-spend-anim' : ''}" style="--n:${n}">${marks}</g>` +
    `<line class="dbi-spend-hotline" x1="0" x2="0" y1="${T}" y2="${T + ih}" opacity="0"/>`;
  geo = { L, T, bw, ih, n, from, series, totals, w };
  if (st.hover >= n) st.hover = -1;
  if (st.hover >= 0) showTip(st.hover);
}

function showTip(k) {
  if (!geo) return;
  const cross = $('.dbi-spend-cross', svg), line = $('.dbi-spend-hotline', svg), marks = $('.dbi-spend-marks', svg);
  st.hover = k;
  $$('.dbi-spend-col.dbi-spend-hot', svg).forEach(c => c.classList.remove('dbi-spend-hot'));
  if (k < 0) {
    tip.classList.remove('dbi-spend-on'); cross.setAttribute('opacity', 0); line.setAttribute('opacity', 0); marks.classList.remove('dbi-spend-dim');
    return;
  }
  const x = geo.L + geo.bw * (k + 0.5);
  if (st.mode === 'daily') {
    cross.setAttribute('x', geo.L + geo.bw * k); cross.setAttribute('opacity', 1);
    const col = $(`.dbi-spend-col[data-k="${k}"]`, svg);
    if (col) col.classList.add('dbi-spend-hot');
    marks.classList.add('dbi-spend-dim');
  } else {
    line.setAttribute('x1', x); line.setAttribute('x2', x); line.setAttribute('opacity', 1);
  }
  const rows = MODELS.map((M, m) => st.models.has(m)
    ? `<li><i style="background:var(--dbi-spend-m${m + 1})"></i><span>${M.id}</span><b>${usd(geo.series[k][m])}</b></li>` : '').join('');
  tip.innerHTML = `<header>${dLong.format(dates[geo.from + k])}${st.mode === 'cumulative' ? ' · running total' : ''}</header><ul>${rows}</ul><footer>Total<b>${usd(geo.totals[k])}</b></footer>`;
  const tw = tip.offsetWidth;
  const left = x + 14 + tw > geo.w ? Math.max(0, x - tw - 14) : x + 14;
  tip.style.translate = `${left}px ${geo.T + 4}px`;
  tip.classList.add('dbi-spend-on');
}

function renderTeams() {
  const A = agg(DAYS - st.range, DAYS - 1, null, st.models), total = A.c || 1;
  const rows = TEAMS.map((t, i) => ({ i, t, name: t.name, req: A.team[i][0], tok: A.team[i][1] + A.team[i][2], spend: A.team[i][3], share: A.team[i][3] / total }));
  const { key, dir } = st.sort;
  rows.sort((a, b) => key === 'name' ? dir * a.name.localeCompare(b.name) : dir * (a[key] - b[key]));
  const focusIdx = Math.max(0, rows.findIndex(r => r.i === st.team));
  tbody.innerHTML = rows.map((r, n) => `<tr data-team="${r.i}" tabindex="${n === focusIdx ? 0 : -1}" aria-selected="${st.team === r.i}" style="--i:${n}">
    <th scope="row">${esc(r.name)}<small>${esc(r.t.lead)}</small></th>
    <td>${nf0.format(r.req)}</td><td>${cmp.format(r.tok)}</td><td>${usd(r.spend)}</td>
    <td><span class="dbi-spend-share"><i style="--w:${(r.share * 100).toFixed(2)}%"></i></span>${pct(r.share)}</td></tr>`).join('');
  tfoot.innerHTML = `<tr><th scope="row">All teams</th><td>${nf0.format(A.r)}</td><td>${cmp.format(A.i + A.o)}</td><td>${usd(A.c)}</td><td>100.0%</td></tr>`;
  $$('.dbi-spend-teams thead th').forEach(th => {
    const b = $('button', th);
    th.setAttribute('aria-sort', b.dataset.sort === key ? (dir < 0 ? 'descending' : 'ascending') : 'none');
  });
}

function setTeam(i) {
  st.team = st.team === i ? null : i;
  $$('tr', tbody).forEach(tr => tr.setAttribute('aria-selected', String(+tr.dataset.team === st.team)));
  chip.hidden = st.team === null;
  if (st.team !== null) $('span', chip).textContent = TEAMS[st.team].name;
  chip.setAttribute('aria-label', st.team === null ? '' : 'Clear team filter ' + TEAMS[st.team].name);
  render(true, true);
}

/* ---------- models ---------- */
function renderModels() {
  const n = st.range, A = agg(DAYS - n, DAYS - 1, st.team, ALL), total = A.c || 1;
  const dsvg = $('.dbi-spend-donut svg');
  let off = 0, segs = '<circle class="dbi-spend-dtrack" cx="90" cy="90" r="70"/>';
  MODELS.forEach((M, m) => {
    const share = A.model[m][3] / total * 100;
