    off += share;
  });
  dsvg.innerHTML = segs;
  const scope = (st.team === null ? 'All teams' : TEAMS[st.team].name) + ' · last ' + n + ' days';
  $('[data-rangelabel]').textContent = scope;
  const center = (title, value, sub) => {
    $('.dbi-spend-dcenter .dbi-spend-eyebrow').textContent = title;
    $('.dbi-spend-dcenter b').textContent = value;
    $('.dbi-spend-dcenter small').textContent = sub;
  };
  const reset = () => center('Total', usd0(A.c), nf0.format(A.r) + ' requests');
  reset();
  $$('.dbi-spend-dseg', dsvg).forEach(c => {
    const m = +c.dataset.m;
    c.addEventListener('pointerenter', () => { center(MODELS[m].id, pct(A.model[m][3] / total), usd(A.model[m][3])); hotRow(m); });
    c.addEventListener('pointerleave', () => { reset(); hotRow(-1); });
  });
  const mt = $('.dbi-spend-models tbody');
  mt.innerHTML = MODELS.map((M, m) => {
    const v = A.model[m];
    return `<tr data-m="${m}" style="--i:${m}"><th scope="row"><span class="dbi-spend-sw" style="background:var(--dbi-spend-m${m + 1})"></span>${M.id}</th>
      <td>$${M.pin.toFixed(2)} / ${M.pout ? '$' + M.pout.toFixed(2) : '—'}</td><td>${nf0.format(v[0])}</td><td>${cmp.format(v[1])}</td><td>${v[2] ? cmp.format(v[2]) : '—'}</td><td>${usd(v[3])}</td><td>${pct(v[3] / total)}</td></tr>`;
  }).join('');
  $('.dbi-spend-models tfoot').innerHTML = `<tr><th scope="row">Total</th><td></td><td>${nf0.format(A.r)}</td><td>${cmp.format(A.i)}</td><td>${cmp.format(A.o)}</td><td>${usd(A.c)}</td><td>100.0%</td></tr>`;
  $$('tr', mt).forEach(tr => {
    const m = +tr.dataset.m;
    tr.addEventListener('pointerenter', () => { const s = $(`.dbi-spend-dseg[data-m="${m}"]`, dsvg); if (s) s.classList.add('dbi-spend-hot'); center(MODELS[m].id, pct(A.model[m][3] / total), usd(A.model[m][3])); });
    tr.addEventListener('pointerleave', () => { $$('.dbi-spend-dseg', dsvg).forEach(s => s.classList.remove('dbi-spend-hot')); reset(); });
  });
  const cpk = MODELS.map((_, m) => A.model[m][0] ? A.model[m][3] / A.model[m][0] * 1000 : 0), cmax = Math.max(...cpk) || 1;
  $('.dbi-spend-units').innerHTML = MODELS.map((M, m) => {
    const v = A.model[m], r = v[0] || 1;
    return `<li style="--i:${m}"><span class="dbi-spend-uname"><span class="dbi-spend-sw" style="background:var(--dbi-spend-m${m + 1})"></span>${M.id}</span>
      <span class="dbi-spend-unum">${nf0.format(v[1] / r)} in · ${v[2] ? nf0.format(v[2] / r) + ' out' : 'embedding'}</span>
      <span class="dbi-spend-ubar"><i style="--w:${(cpk[m] / cmax * 100).toFixed(2)}%;background:var(--dbi-spend-m${m + 1})"></i></span><b>${usd(cpk[m])}</b></li>`;
  }).join('');
  function hotRow(m) { $$('tr', mt).forEach(tr => tr.classList.toggle('dbi-spend-hot', +tr.dataset.m === m)); }
}

/* ---------- budgets ---------- */
const SEP = [], AUG = [];
dates.forEach((d, k) => { if (d.getUTCMonth() === 8) SEP.push(k); else if (d.getUTCMonth() === 7) AUG.push(k); });
const BUD = TEAMS.map((t, ti) => {
  const sum = ks => ks.reduce((a, d) => a + data[d][ti].reduce((s, v) => s + v[3], 0), 0);
  const aug = sum(AUG), mtd = sum(SEP);
  const budget = Math.round(aug / AUG.length * 30 * t.budget / 50000) * 50000;
  const proj = Math.round(mtd / SEP.length * 30);
  const cum = []; let run = 0;
  SEP.forEach(d => { run += data[d][ti].reduce((s, v) => s + v[3], 0); cum.push(run); });
  const r = proj / budget;
  return { ti, mtd, budget, proj, cum, r, s: r > 1 ? 'over' : r > 0.95 ? 'risk' : 'ok' };
});
st.bteam = BUD.reduce((a, b) => (b.r > a.r ? b : a)).ti;

function renderBudgets() {
  const list = $('.dbi-spend-blist');
  const rows = BUD.slice().sort((a, b) => b.r - a.r);
  const label = b => b.s === 'over' ? 'Over by ' + usd0(b.proj - b.budget) : b.s === 'risk' ? 'At risk' : 'On track';
  const tot = BUD.reduce((a, b) => ({ mtd: a.mtd + b.mtd, budget: a.budget + b.budget, proj: a.proj + b.proj }), { mtd: 0, budget: 0, proj: 0 });
  list.innerHTML = rows.map((b, n) => `<li class="dbi-spend-brow" role="option" data-team="${b.ti}" tabindex="${b.ti === st.bteam ? 0 : -1}" aria-selected="${b.ti === st.bteam}" style="--i:${n}">
      <span><b>${esc(TEAMS[b.ti].name)}</b></span><span class="dbi-spend-pill" data-s="${b.s}">${label(b)}</span>
      <span class="dbi-spend-bbar"${b.proj > b.budget ? ' data-over' : ''} style="--i:${n}"><u style="--w:${(b.proj / b.budget * 100).toFixed(1)}%"></u><i style="--w:${(b.mtd / b.budget * 100).toFixed(1)}%"></i></span>
      <span class="dbi-spend-nums">${usd0(b.mtd)} spent</span><span class="dbi-spend-nums">${usd0(b.proj)} projected / ${usd0(b.budget)}</span></li>`).join('') +
    `<li class="dbi-spend-brow" aria-hidden="true" style="--i:${rows.length};cursor:default"><span><b>All teams</b></span><span class="dbi-spend-nums">${pct(tot.proj / tot.budget, 0)} of budget</span>
      <span class="dbi-spend-nums" style="text-align:left">${usd0(tot.mtd)} spent</span><span class="dbi-spend-nums">${usd0(tot.proj)} projected / ${usd0(tot.budget)}</span></li>`;
  drawBurn(true);
}

let bgeo = null;
function drawBurn(animate) {
  const w = burn.clientWidth, h = burn.clientHeight;
  if (!w || !h) return;
  const b = BUD.find(x => x.ti === st.bteam), t = TEAMS[b.ti];
  $('[data-burntitle]').textContent = t.name + ' · September burn';
  $('[data-burnhint]').textContent = t.lead;
  const { top, step } = niceScale(Math.max(b.budget, b.proj) * 1.06, 4);
  const L = 50, R = 14, T = 14, B = 24, iw = w - L - R, ih = h - T - B;
  const x = d => L + (d - 1) / 29 * iw, y = v => T + ih - v / top * ih;
  let g = '';
  for (let v = 0; v <= top + 1e-6; v += step) g += `<line class="dbi-spend-grid${v === 0 ? ' dbi-spend-base' : ''}" x1="${L}" x2="${w - R}" y1="${y(v)}" y2="${y(v)}"/><text class="dbi-spend-ytick" x="${L - 8}" y="${y(v)}" dy="0.33em">${usdAxis(v)}</text>`;
  [1, 8, 15, 22, 30].forEach(d => { g += `<text class="dbi-spend-xtick" x="${x(d)}" y="${h - 6}">Sep ${d}</text>`; });
  const n = b.cum.length;
  const pts = b.cum.map((v, k) => `${x(k + 1).toFixed(2)},${y(v).toFixed(2)}`);
  const area = `M${x(1)},${y(0)}L${pts.join('L')}L${x(n)},${y(0)}Z`;
  const an = animate && !reduce ? ' dbi-spend-anim' : '';
  g += `<line class="dbi-spend-today" x1="${x(n)}" x2="${x(n)}" y1="${T}" y2="${T + ih}"/><text class="dbi-spend-lab" x="${x(n) - 6}" y="${T + 10}" text-anchor="end">Today</text>`;
  g += `<line class="dbi-spend-budgetline" x1="${L}" x2="${w - R}" y1="${y(b.budget)}" y2="${y(b.budget)}"/><text class="dbi-spend-lab" x="${L + 6}" y="${y(b.budget) - 6}">Budget ${usd0(b.budget)}</text>`;
  g += `<g class="${an}"><path class="dbi-spend-burnarea" d="${area}"/><path class="dbi-spend-burnline" d="M${pts.join('L')}"/></g>`;
  g += `<path class="dbi-spend-proj" d="M${x(n)},${y(b.cum[n - 1])}L${x(30)},${y(b.proj)}"/><circle class="dbi-spend-dot" cx="${x(30)}" cy="${y(b.proj)}" r="3.5"/>`;
  g += `<text class="dbi-spend-lab" x="${x(30)}" y="${y(b.proj) - 9}" text-anchor="end">${usd0(b.proj)}</text>`;
  g += `<rect class="dbi-spend-cross" x="0" y="${T}" width="${iw / 29}" height="${ih}" opacity="0"/><circle class="dbi-spend-dot dbi-spend-hdot" r="4" cx="0" cy="0" opacity="0"/>`;
  bsvg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  bsvg.innerHTML = g;
  bgeo = { b, x, y, n, w, T, step: iw / 29 };
  if (st.bhover > 0) showBurnTip(st.bhover);
}
function showBurnTip(d) {
  if (!bgeo) return;
  st.bhover = d;
  const cross = $('.dbi-spend-cross', bsvg), dot = $('.dbi-spend-hdot', bsvg);
  if (d < 1) { btip.classList.remove('dbi-spend-on'); cross.setAttribute('opacity', 0); dot.setAttribute('opacity', 0); return; }
  const { b, x, y, n } = bgeo;
  const actual = d <= n;
  const v = actual ? b.cum[d - 1] : Math.round(b.cum[n - 1] + (b.proj - b.cum[n - 1]) * (d - n) / (30 - n));
  const daily = actual ? b.cum[d - 1] - (d > 1 ? b.cum[d - 2] : 0) : (b.proj - b.cum[n - 1]) / (30 - n);
  cross.setAttribute('x', x(d) - bgeo.step / 2); cross.setAttribute('opacity', 1);
  dot.setAttribute('cx', x(d)); dot.setAttribute('cy', y(v)); dot.setAttribute('opacity', 1);
  btip.innerHTML = `<header>Sep ${d}${actual ? '' : ' · projected'}</header><ul><li><span>Day spend</span><b>${usd(daily)}</b></li><li><span>Running total</span><b>${usd(v)}</b></li><li><span>Budget used</span><b>${pct(v / b.budget)}</b></li></ul>`;
  const tw = btip.offsetWidth, px = x(d);
  btip.style.translate = `${px + 14 + tw > bgeo.w ? px - tw - 14 : px + 14}px ${bgeo.T + 18}px`;
  btip.classList.add('dbi-spend-on');
}
function setBudgetTeam(ti, focus) {
  st.bteam = ti;
  $$('.dbi-spend-brow[role="option"]').forEach(li => {
    const on = +li.dataset.team === ti;
    li.setAttribute('aria-selected', String(on)); li.tabIndex = on ? 0 : -1;
    if (on && focus) li.focus();
  });
  drawBurn(true);
}

/* ---------- orchestration ---------- */
function render(animate, keepTable) {
  if (st.view === 'overview') { renderKpis(); drawChart(animate); if (!keepTable) renderTeams(); }
  else if (st.view === 'models') renderModels();
  else renderBudgets();
}
function setView(v) {
  if (v === st.view) return;
  vt(() => {
    st.view = v; root.dataset.view = v;
    $$('.dbi-spend-navbtn').forEach(b => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
    $$('.dbi-spend-view').forEach(s => { s.hidden = s.dataset.view !== v; });
    $('.dbi-spend-range').hidden = v === 'budgets';
    chip.hidden = v === 'budgets' || st.team === null;
    render(true);
  });
}
function radio(group, attr, value) {
  $$('[role="radio"]', group).forEach(b => {
    const on = b.dataset[attr] === String(value);
    b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1;
  });
}
function radioKeys(group, pick) {
  group.addEventListener('keydown', e => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    const bs = $$('[role="radio"]', group), i = bs.findIndex(b => b.getAttribute('aria-checked') === 'true');
    const nb = bs[(i + (e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 1) + bs.length) % bs.length];
    nb.focus(); pick(nb);
  });
}

/* nav */
$('.dbi-spend-nav').addEventListener('click', e => { const b = e.target.closest('.dbi-spend-navbtn'); if (b) setView(b.dataset.view); });
/* range */
const rangeSeg = $('.dbi-spend-range');
const pickRange = b => { st.range = +b.dataset.range; radio(rangeSeg, 'range', st.range); st.hover = -1; tip.classList.remove('dbi-spend-on'); render(true); };
rangeSeg.addEventListener('click', e => { const b = e.target.closest('[data-range]'); if (b) pickRange(b); });
radioKeys(rangeSeg, pickRange);
radio(rangeSeg, 'range', st.range);
/* chart mode */
const modeSeg = $('.dbi-spend-mode');
const pickMode = b => { st.mode = b.dataset.mode; radio(modeSeg, 'mode', st.mode); drawChart(true); };
modeSeg.addEventListener('click', e => { const b = e.target.closest('[data-mode]'); if (b) pickMode(b); });
radioKeys(modeSeg, pickMode);
radio(modeSeg, 'mode', st.mode);
/* legend */
$('.dbi-spend-legend').addEventListener('click', e => {
  const b = e.target.closest('.dbi-spend-lg'); if (!b) return;
  const m = +b.dataset.m;
  if (st.models.has(m)) { if (st.models.size === 1) return; st.models.delete(m); } else st.models.add(m);
  b.setAttribute('aria-pressed', String(st.models.has(m)));
  renderKpis(); drawChart(false); renderTeams();
});
/* chart hover + keys */
chart.addEventListener('pointermove', e => {
  if (!geo) return;
  const k = Math.floor((e.clientX - chart.getBoundingClientRect().left - geo.L) / geo.bw);
  showTip(k >= 0 && k < geo.n ? k : -1);
});
chart.addEventListener('pointerleave', () => showTip(-1));
chart.addEventListener('blur', () => showTip(-1));
chart.addEventListener('keydown', e => {
  if (!geo) return;
  const k = st.hover < 0 ? geo.n - 1 : st.hover;
  if (e.key === 'ArrowLeft') showTip(Math.max(0, st.hover < 0 ? k : k - 1));
  else if (e.key === 'ArrowRight') showTip(Math.min(geo.n - 1, st.hover < 0 ? k : k + 1));
  else if (e.key === 'Home') showTip(0);
  else if (e.key === 'End') showTip(geo.n - 1);
  else if (e.key === 'Escape') showTip(-1);
  else return;
  e.preventDefault();
});
/* team table: sort + select */
$('.dbi-spend-teams thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const key = b.dataset.sort;
  st.sort = { key, dir: st.sort.key === key ? -st.sort.dir : key === 'name' ? 1 : -1 };
  renderTeams();
});
tbody.addEventListener('click', e => { const tr = e.target.closest('tr'); if (tr) setTeam(+tr.dataset.team); });
tbody.addEventListener('keydown', e => {
  const tr = e.target.closest('tr'); if (!tr) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setTeam(+tr.dataset.team); return; }
  const next = e.key === 'ArrowDown' ? tr.nextElementSibling : e.key === 'ArrowUp' ? tr.previousElementSibling : null;
  if (next) { e.preventDefault(); tr.tabIndex = -1; next.tabIndex = 0; next.focus(); }
});
chip.addEventListener('click', () => setTeam(st.team));
/* budgets */
const blist = $('.dbi-spend-blist');
blist.addEventListener('click', e => { const li = e.target.closest('[role="option"]'); if (li) setBudgetTeam(+li.dataset.team); });
blist.addEventListener('keydown', e => {
  const li = e.target.closest('[role="option"]'); if (!li) return;
  const opts = $$('[role="option"]', blist), i = opts.indexOf(li);
  const j = e.key === 'ArrowDown' ? i + 1 : e.key === 'ArrowUp' ? i - 1 : -1;
  if (opts[j]) { e.preventDefault(); setBudgetTeam(+opts[j].dataset.team, true); }
});
burn.addEventListener('pointermove', e => {
  if (!bgeo) return;
  const d = Math.round((e.clientX - burn.getBoundingClientRect().left - 50) / bgeo.step) + 1;
  showBurnTip(d >= 1 && d <= 30 ? d : 0);
});
burn.addEventListener('pointerleave', () => showBurnTip(0));
burn.addEventListener('blur', () => showBurnTip(0));
burn.addEventListener('keydown', e => {
  const d = st.bhover < 1 ? bgeo.n : st.bhover;
  if (e.key === 'ArrowLeft') showBurnTip(Math.max(1, st.bhover < 1 ? d : d - 1));
  else if (e.key === 'ArrowRight') showBurnTip(Math.min(30, st.bhover < 1 ? d : d + 1));
  else if (e.key === 'Escape') showBurnTip(0);
  else return;
  e.preventDefault();
});

/* resize: redraw at the new size without replaying the entry */
let rq = 0, lastW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (rq) return;
  rq = requestAnimationFrame(() => {
    if (!root.isConnected) return;
    rq = 0;
    const w = root.clientWidth;
    if (w === lastW) return;
    lastW = w;
    if (st.view === 'overview') drawChart(false);
    else if (st.view === 'budgets') drawBurn(false);
  });
});
ro.observe(root);

renderLegend();
lastW = root.clientWidth;
render(true);

css:
@keyframes dbi-latency-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbi-latency-blurin { from { opacity: 0.2; filter: blur(5px); transform: translateY(3px); } }
@keyframes dbi-latency-grow { from { transform: scaleY(0); } }
@keyframes dbi-latency-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

.dbi-latency {
  /* re-theme with these */
  --dbi-latency-bg: oklch(0.175 0.006 75);
  --dbi-latency-ink: oklch(0.94 0.012 85);
  --dbi-latency-accent: oklch(0.82 0.15 76);
  --dbi-latency-hot: oklch(0.7 0.18 32);
  /* heat ramp, read by the canvas */
  --dbi-latency-heat-lo: oklch(0.29 0.04 58);
  --dbi-latency-heat-mid: oklch(0.64 0.15 52);
  --dbi-latency-heat-hi: oklch(0.97 0.06 95);
  /* derived */
  --dbi-latency-panel: color-mix(in oklch, var(--dbi-latency-bg), white 3.5%);
  --dbi-latency-raise: color-mix(in oklch, var(--dbi-latency-bg), white 7%);
  --dbi-latency-line: color-mix(in oklch, var(--dbi-latency-ink) 10%, transparent);
  --dbi-latency-line-2: color-mix(in oklch, var(--dbi-latency-ink) 18%, transparent);
  --dbi-latency-muted: color-mix(in oklch, var(--dbi-latency-ink) 58%, var(--dbi-latency-bg));
  --dbi-latency-faint: color-mix(in oklch, var(--dbi-latency-ink) 36%, var(--dbi-latency-bg));
  --dbi-latency-p50: color-mix(in oklch, var(--dbi-latency-ink) 85%, var(--dbi-latency-bg));
  --dbi-latency-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --dbi-latency-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbi-latency-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbi-latency-bg);
  color: var(--dbi-latency-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: dark;
  accent-color: var(--dbi-latency-accent);
  box-shadow: inset 0 0 0 1px var(--dbi-latency-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbi-latency-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbi-latency-eyebrow { font: 600 10.5px/1.2 var(--dbi-latency-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbi-latency-muted); }

  .dbi-latency-app {
    display: grid; height: 100%;
    grid-template-columns: 228px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side top" "side main";
  }

  /* ---------- side ---------- */
  .dbi-latency-side {
    grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 10px;
    padding: 18px 12px 14px; border-right: 1px solid var(--dbi-latency-line);
    background: color-mix(in oklch, var(--dbi-latency-bg), black 18%);
  }
  .dbi-latency-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 14px; }
  .dbi-latency-brand svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; fill: none; stroke: var(--dbi-latency-bg); stroke-width: 1.8; stroke-linecap: round; background: var(--dbi-latency-accent); }
  .dbi-latency-brand span { display: grid; line-height: 1.2; }
  .dbi-latency-brand b { font-weight: 700; letter-spacing: -0.01em; }
  .dbi-latency-brand small { font-size: 11px; color: var(--dbi-latency-muted); }
  .dbi-latency-sidehead { padding: 0 8px; }
  .dbi-latency-models { display: grid; gap: 2px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbi-latency-line-2) transparent; }
  .dbi-latency-model {
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; align-items: center;
    padding: 8px 10px; border-radius: 9px; cursor: pointer;
    transition: background-color 160ms var(--dbi-latency-ease);
    animation: dbi-latency-rise 500ms var(--dbi-latency-ease) both; animation-delay: calc(var(--i) * 60ms);
  }
  .dbi-latency-model:hover { background: color-mix(in oklch, var(--dbi-latency-ink) 5%, transparent); }
  .dbi-latency-model[aria-selected="true"] { background: var(--dbi-latency-raise); box-shadow: inset 0 0 0 1px var(--dbi-latency-line); }
  .dbi-latency-model[aria-selected="true"]::before { content: ""; position: absolute; left: -12px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbi-latency-accent); }
  .dbi-latency-model b { font: 600 12.5px var(--dbi-latency-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbi-latency-model small { font: 11px var(--dbi-latency-mono); color: var(--dbi-latency-muted); }
  .dbi-latency-model .dbi-latency-mv { font: 600 12px var(--dbi-latency-mono); text-align: right; font-variant-numeric: tabular-nums; }
  .dbi-latency-model .dbi-latency-mv[data-bad] { color: var(--dbi-latency-hot); }
  .dbi-latency-model svg { grid-column: 1 / -1; width: 100%; height: 22px; margin-top: 4px; overflow: visible; }
  .dbi-latency-model polyline { fill: none; stroke: var(--dbi-latency-muted); stroke-width: 1.25; vector-effect: non-scaling-stroke; }
  .dbi-latency-model[aria-selected="true"] polyline { stroke: var(--dbi-latency-accent); }
  .dbi-latency-model .dbi-latency-slol { stroke: var(--dbi-latency-hot); stroke-width: 1; stroke-dasharray: 2 2; opacity: 0.7; vector-effect: non-scaling-stroke; }
