  --dbi-evals-ink: oklch(0.24 0.03 255);
  --dbi-evals-accent: oklch(0.47 0.09 196);
  --dbi-evals-bad: oklch(0.57 0.2 27);
  /* derived */
  --dbi-evals-good: color-mix(in oklch, var(--dbi-evals-accent), oklch(0.62 0.15 160) 55%);
  --dbi-evals-watch: oklch(0.74 0.14 75);
  --dbi-evals-card: #fff;
  --dbi-evals-sunk: color-mix(in oklch, var(--dbi-evals-paper), var(--dbi-evals-ink) 4%);
  --dbi-evals-line: color-mix(in oklch, var(--dbi-evals-ink) 10%, transparent);
  --dbi-evals-line-2: color-mix(in oklch, var(--dbi-evals-ink) 20%, transparent);
  --dbi-evals-muted: color-mix(in oklch, var(--dbi-evals-ink) 60%, var(--dbi-evals-paper));
  --dbi-evals-faint: color-mix(in oklch, var(--dbi-evals-ink) 40%, var(--dbi-evals-paper));
  --dbi-evals-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbi-evals-spring: linear(0, 0.013, 0.05 3%, 0.2 6.5%, 0.73 15%, 0.94 20%, 1.03 24%, 1.06 28%, 1.05 33%, 1.01 41%, 0.995 50%, 1);
  --dbi-evals-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbi-evals-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbi-evals-paper);
  color: var(--dbi-evals-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbi-evals-accent);
  box-shadow: inset 0 0 0 1px var(--dbi-evals-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbi-evals-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbi-evals-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbi-evals-muted); }

  .dbi-evals-app { display: grid; height: 100%; grid-template-columns: 180px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }
  .dbi-evals-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; border-right: 1px solid var(--dbi-evals-line); background: var(--dbi-evals-card); }
  .dbi-evals-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbi-evals-brand svg { width: 30px; height: 30px; padding: 5px; border-radius: 8px; background: var(--dbi-evals-ink); fill: none; stroke: var(--dbi-evals-paper); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbi-evals-brand span { display: grid; line-height: 1.2; }
  .dbi-evals-brand b { font-weight: 700; letter-spacing: -0.01em; }
  .dbi-evals-brand small { font-size: 11px; color: var(--dbi-evals-muted); }
  .dbi-evals-nav { display: grid; gap: 2px; }
  .dbi-evals-navbtn { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbi-evals-muted); font-weight: 560; transition: background-color 150ms, color 150ms; }
  .dbi-evals-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbi-evals-navbtn:hover { color: var(--dbi-evals-ink); background: var(--dbi-evals-sunk); }
  .dbi-evals-navbtn[aria-current="page"] { color: var(--dbi-evals-ink); background: color-mix(in oklch, var(--dbi-evals-accent) 10%, var(--dbi-evals-card)); }
  .dbi-evals-navbtn[aria-current="page"] svg { color: var(--dbi-evals-accent); }
  .dbi-evals-project { margin-top: auto; display: grid; gap: 3px; padding: 12px 8px 0; border-top: 1px solid var(--dbi-evals-line); }
  .dbi-evals-project b { font: 600 12px var(--dbi-evals-mono); overflow-wrap: anywhere; }
  .dbi-evals-project small { font-size: 11.5px; color: var(--dbi-evals-muted); }

  .dbi-evals-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 16px 20px 12px; border-bottom: 1px solid var(--dbi-evals-line); }
  .dbi-evals-title { display: grid; gap: 2px; }
  .dbi-evals-h { font-size: clamp(19px, 1.1rem + 0.7cqi, 26px); font-weight: 700; letter-spacing: -0.03em; line-height: 1.1; }
  .dbi-evals-tools { display: flex; flex-wrap: wrap; gap: 8px; }
  .dbi-evals-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbi-evals-sunk); box-shadow: inset 0 0 0 1px var(--dbi-evals-line); }
  .dbi-evals-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dbi-evals-muted); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbi-evals-seg [data-v="atlas"], .dbi-evals-seg [data-v="nimbus"] { font-family: var(--dbi-evals-mono); font-size: 11.5px; }
  .dbi-evals-seg button:hover { color: var(--dbi-evals-ink); }
  .dbi-evals-seg button[aria-checked="true"] { color: var(--dbi-evals-ink); background: var(--dbi-evals-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbi-evals-ink) 14%, transparent), 0 0 0 1px var(--dbi-evals-line); }

  .dbi-evals-main { grid-area: main; min-height: 0; overflow: auto; padding: 14px 20px 18px; scrollbar-width: thin; scrollbar-color: var(--dbi-evals-line-2) transparent; }
  .dbi-evals-mview { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 268px; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "sum sum" "mat det"; min-height: 100%; }
  .dbi-evals-panel { min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbi-evals-card); box-shadow: 0 0 0 1px var(--dbi-evals-line), 0 1px 3px color-mix(in oklch, var(--dbi-evals-ink) 5%, transparent); }
  .dbi-evals-matpanel { grid-area: mat; }
  .dbi-evals-detail { grid-area: det; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbi-evals-line-2) transparent; }
  .dbi-evals-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding: 12px 14px 10px; }
  .dbi-evals-ph h3 { font-size: 13.5px; font-weight: 650; margin-right: auto; }
  .dbi-evals-hint { font-size: 11.5px; color: var(--dbi-evals-faint); }
  .dbi-evals-scroll { position: relative; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbi-evals-line-2) transparent; }

  /* ---------- summary ---------- */
  .dbi-evals-summary { grid-area: sum; display: flex; flex-wrap: wrap; align-items: stretch; gap: 1px; border-radius: 12px; overflow: hidden; background: var(--dbi-evals-line); box-shadow: 0 0 0 1px var(--dbi-evals-line); }
  .dbi-evals-summary > div { flex: 1 1 120px; display: grid; gap: 2px; padding: 10px 14px; background: var(--dbi-evals-card); }
  .dbi-evals-summary > div > * { animation: dbi-evals-rise 500ms var(--dbi-evals-ease) both; animation-delay: calc(var(--i) * 50ms); }
  .dbi-evals-summary b { font: 650 clamp(17px, 0.85rem + 0.8cqi, 22px)/1.15 system-ui, sans-serif; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
  .dbi-evals-summary small { font-size: 11.5px; color: var(--dbi-evals-muted); font-variant-numeric: tabular-nums; }
  .dbi-evals-summary .dbi-evals-gate { flex: 1.4 1 200px; align-content: center; }
  .dbi-evals-gate b { display: inline-flex; align-items: center; gap: 8px; font-size: 14px; letter-spacing: -0.01em; }
  .dbi-evals-gate b i { width: 9px; height: 9px; border-radius: 50%; background: var(--dbi-evals-good); box-shadow: 0 0 0 4px color-mix(in oklch, var(--dbi-evals-good) 18%, transparent); }
  .dbi-evals-gate[data-blocked] b { color: var(--dbi-evals-bad); }
  .dbi-evals-gate[data-blocked] b i { background: var(--dbi-evals-bad); box-shadow: 0 0 0 4px color-mix(in oklch, var(--dbi-evals-bad) 18%, transparent); }
  .dbi-evals-pos { color: var(--dbi-evals-good); }
  .dbi-evals-neg { color: var(--dbi-evals-bad); }

  /* ---------- switch + key ---------- */
  .dbi-evals-switch { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 550; color: var(--dbi-evals-muted); cursor: pointer; }
  .dbi-evals-switch input { appearance: none; margin: 0; width: 28px; height: 16px; border-radius: 99px; background: var(--dbi-evals-line-2); position: relative; cursor: pointer; transition: background-color 200ms var(--dbi-evals-ease); }
  .dbi-evals-switch input::after { content: ""; position: absolute; inset: 2px auto 2px 2px; width: 12px; border-radius: 50%; background: var(--dbi-evals-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbi-evals-ink) 30%, transparent); transition: translate 260ms var(--dbi-evals-spring); }
  .dbi-evals-switch input:checked { background: var(--dbi-evals-accent); }
  .dbi-evals-switch input:checked::after { translate: 12px 0; }
  .dbi-evals-switch:has(input:checked) { color: var(--dbi-evals-ink); }
  .dbi-evals-key { display: flex; gap: 12px; font-size: 11px; color: var(--dbi-evals-muted); }
  .dbi-evals-key span { display: inline-flex; align-items: center; gap: 5px; }
  .dbi-evals-key i { width: 11px; height: 11px; border-radius: 3px; }
  .dbi-evals-kreg { box-shadow: inset 0 0 0 2px var(--dbi-evals-bad); }
  .dbi-evals-kimp { background: linear-gradient(225deg, var(--dbi-evals-good) 45%, transparent 46%); box-shadow: inset 0 0 0 1px var(--dbi-evals-line-2); }
  .dbi-evals-kwatch { background: radial-gradient(circle at 50% 50%, var(--dbi-evals-watch) 2.5px, transparent 3px); box-shadow: inset 0 0 0 1px var(--dbi-evals-line-2); }

  /* ---------- matrix (subgrid rows keep every column aligned) ---------- */
  .dbi-evals-matrix { display: grid; grid-template-columns: minmax(132px, 1.4fr) repeat(var(--cols, 9), minmax(48px, 1fr)); min-width: 584px; padding: 0 10px 10px; }
  .dbi-evals-mrow { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: stretch; }
  .dbi-evals-mrow[data-out] { display: none; }
  .dbi-evals-mhead { position: sticky; top: 0; z-index: 2; background: var(--dbi-evals-card); border-bottom: 1px solid var(--dbi-evals-line); margin-bottom: 4px; }
  .dbi-evals-vh { display: grid; justify-items: center; gap: 0; padding: 4px 2px 6px; border-radius: 8px; font: 650 12px var(--dbi-evals-mono); color: var(--dbi-evals-muted); transition: color 150ms, background-color 150ms; }
  .dbi-evals-vh small { font: 400 10px system-ui, sans-serif; color: var(--dbi-evals-faint); }
  .dbi-evals-vh:hover { color: var(--dbi-evals-ink); background: var(--dbi-evals-sunk); }
  .dbi-evals-vh[aria-selected="true"] { color: var(--dbi-evals-ink); background: color-mix(in oklch, var(--dbi-evals-accent) 10%, var(--dbi-evals-card)); }
  .dbi-evals-vh[data-prod]::after { content: "prod"; font: 700 8.5px system-ui, sans-serif; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbi-evals-accent); }
  .dbi-evals-rh { display: grid; align-content: center; gap: 0; padding: 0 10px 0 4px; min-width: 0; }
  .dbi-evals-rh b { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbi-evals-rh small { font: 10.5px var(--dbi-evals-mono); color: var(--dbi-evals-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbi-evals-mrow:has(.dbi-evals-c[aria-selected="true"]) .dbi-evals-rh b { color: var(--dbi-evals-accent); }
  .dbi-evals-c {
    --mix: calc(var(--s) * 1%);
    position: relative; display: grid; place-content: center; justify-items: center; gap: 0;
    height: 40px; margin: 2px; border-radius: 7px; cursor: pointer;
    background: color-mix(in oklch, var(--dbi-evals-accent) var(--mix), var(--dbi-evals-card));
    font: 600 12px/1.1 var(--dbi-evals-mono); font-variant-numeric: tabular-nums;
    transition: transform 220ms var(--dbi-evals-spring), box-shadow 160ms;
    animation: dbi-evals-pop 560ms var(--dbi-evals-ease) both; animation-delay: calc(var(--i) * 22ms);
  }
  .dbi-evals-c[data-dark] { color: var(--dbi-evals-paper); }
  .dbi-evals-c small { font-size: 9.5px; font-weight: 500; opacity: 0.8; }
  .dbi-evals-c:hover { transform: scale(1.06); z-index: 1; box-shadow: 0 6px 16px color-mix(in oklch, var(--dbi-evals-ink) 18%, transparent); }
  .dbi-evals-c.dbi-evals-col { box-shadow: 0 0 0 1px color-mix(in oklch, var(--dbi-evals-ink) 25%, transparent); }
  .dbi-evals-c[aria-selected="true"] { box-shadow: 0 0 0 2px var(--dbi-evals-card), 0 0 0 4px var(--dbi-evals-ink); z-index: 1; }
  .dbi-evals-c:focus-visible { outline-offset: 3px; }
  .dbi-evals-c[data-flag="reg"]::after {
    content: ""; position: absolute; inset: -1px; border-radius: 8px; border: 2px solid var(--dbi-evals-bad);
    -webkit-mask-image: conic-gradient(#000 var(--dbi-evals-a), transparent 0); mask-image: conic-gradient(#000 var(--dbi-evals-a), transparent 0);
    animation: dbi-evals-sweep 1100ms var(--dbi-evals-ease) both; animation-delay: calc(var(--i) * 22ms + 500ms);
  }
  .dbi-evals-c[data-flag="reg"] small { color: var(--dbi-evals-bad); opacity: 1; font-weight: 700; }
  .dbi-evals-c[data-flag="reg"][data-dark] small { color: var(--dbi-evals-paper); }
  .dbi-evals-c[data-flag="reg"][data-dark] { background: color-mix(in oklch, var(--dbi-evals-bad) 70%, var(--dbi-evals-ink)); }
  .dbi-evals-c[data-flag="imp"]::before { content: ""; position: absolute; top: 3px; right: 3px; width: 8px; height: 8px; background: var(--dbi-evals-good); clip-path: polygon(0 0, 100% 0, 100% 100%); border-radius: 1px; }
  .dbi-evals-c[data-flag="imp"][data-dark]::before { background: var(--dbi-evals-paper); }
  .dbi-evals-c[data-flag="watch"]::before { content: ""; position: absolute; top: 4px; right: 4px; width: 5px; height: 5px; border-radius: 50%; background: var(--dbi-evals-watch); }

  /* ---------- detail ---------- */
  .dbi-evals-detail > * { animation: dbi-evals-rise 420ms var(--dbi-evals-ease) both; }
  .dbi-evals-dhead { padding: 14px 16px 6px; display: grid; gap: 4px; }
  .dbi-evals-dhead h3 { font-size: 15px; font-weight: 680; letter-spacing: -0.015em; }
  .dbi-evals-dhead p { font-size: 12px; color: var(--dbi-evals-muted); }
  .dbi-evals-dscore { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 10px; padding: 6px 16px 2px; }
  .dbi-evals-dscore b { font-size: 30px; font-weight: 700; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
  .dbi-evals-pill { font: 650 11.5px var(--dbi-evals-mono); padding: 2px 7px; border-radius: 99px; background: var(--dbi-evals-sunk); }
  .dbi-evals-pill[data-flag="reg"] { color: var(--dbi-evals-bad); background: color-mix(in oklch, var(--dbi-evals-bad) 10%, var(--dbi-evals-card)); }
  .dbi-evals-pill[data-flag="imp"] { color: color-mix(in oklch, var(--dbi-evals-good), var(--dbi-evals-ink) 25%); background: color-mix(in oklch, var(--dbi-evals-good) 12%, var(--dbi-evals-card)); }
  .dbi-evals-pill[data-flag="watch"] { color: color-mix(in oklch, var(--dbi-evals-watch), var(--dbi-evals-ink) 45%); background: color-mix(in oklch, var(--dbi-evals-watch) 18%, var(--dbi-evals-card)); }
  .dbi-evals-dmeta { padding: 0 16px 8px; font-size: 11.5px; color: var(--dbi-evals-muted); font-variant-numeric: tabular-nums; }
  .dbi-evals-spark { position: relative; height: 132px; margin: 0 10px; }
  .dbi-evals-spark svg { width: 100%; height: 100%; overflow: visible; }
  .dbi-evals-band { fill: color-mix(in oklch, var(--dbi-evals-accent) 13%, transparent); }
  .dbi-evals-sline { fill: none; stroke: var(--dbi-evals-accent); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: calc(var(--len, 0) * 1px) 99999px; animation: dbi-evals-draw 900ms var(--dbi-evals-ease) both; }
  .dbi-evals-pt { fill: var(--dbi-evals-card); stroke: var(--dbi-evals-accent); stroke-width: 2; transition: r 200ms var(--dbi-evals-spring); }
  .dbi-evals-pt[data-flag="reg"] { stroke: var(--dbi-evals-bad); fill: var(--dbi-evals-bad); }
  .dbi-evals-pt[data-flag="imp"] { fill: var(--dbi-evals-good); stroke: var(--dbi-evals-good); }
  .dbi-evals-pt[data-sel] { stroke: var(--dbi-evals-ink); stroke-width: 2.5; }
  .dbi-evals-pt[data-hot] { r: 6; }
  .dbi-evals-axis { font: 10px var(--dbi-evals-mono); fill: var(--dbi-evals-faint); }
  .dbi-evals-gl { stroke: var(--dbi-evals-line); }
  .dbi-evals-readout { margin: 2px 16px 8px; min-height: 18px; font: 11.5px var(--dbi-evals-mono); color: var(--dbi-evals-muted); font-variant-numeric: tabular-nums; }
  .dbi-evals-cases { display: grid; gap: 8px; padding: 6px 12px 14px; }
  .dbi-evals-cases h4 { font-size: 12px; font-weight: 650; padding: 4px 4px 0; }
  .dbi-evals-cases h4 span { color: var(--dbi-evals-muted); font-weight: 500; }
  .dbi-evals-case { border-radius: 9px; padding: 9px 10px; background: var(--dbi-evals-sunk); display: grid; gap: 4px; font-size: 12px; animation: dbi-evals-rise 460ms var(--dbi-evals-ease) both; animation-delay: calc(var(--i) * 70ms + 150ms); }
  .dbi-evals-case code { font: 600 10.5px var(--dbi-evals-mono); color: var(--dbi-evals-muted); }
  .dbi-evals-case q { quotes: none; font-weight: 550; }
  .dbi-evals-case p { color: var(--dbi-evals-muted); font-size: 11.5px; }
  .dbi-evals-case p b { font-weight: 600; color: var(--dbi-evals-ink); }
  .dbi-evals-case[data-k="fail"] { box-shadow: inset 2px 0 0 var(--dbi-evals-bad); }
  .dbi-evals-case[data-k="pass"] { box-shadow: inset 2px 0 0 var(--dbi-evals-good); }
  .dbi-evals-empty { padding: 4px 4px 0; font-size: 12px; color: var(--dbi-evals-muted); }

  /* ---------- runs ---------- */
  .dbi-evals-runs { width: 100%; min-width: 640px; border-collapse: collapse; font-variant-numeric: tabular-nums; }
  .dbi-evals-runs th, .dbi-evals-runs td { padding: 9px 12px; text-align: left; vertical-align: top; }
  .dbi-evals-runs thead th { position: sticky; top: 0; z-index: 1; background: var(--dbi-evals-card); font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbi-evals-muted); border-bottom: 1px solid var(--dbi-evals-line); white-space: nowrap; }
  .dbi-evals-runs thead button { font: inherit; letter-spacing: inherit; text-transform: inherit; }
  .dbi-evals-runs th[aria-sort="ascending"] button::after { content: " ↑"; }
  .dbi-evals-runs th[aria-sort="descending"] button::after { content: " ↓"; }
  .dbi-evals-runs th[aria-sort$="ending"] button { color: var(--dbi-evals-ink); }
  .dbi-evals-runs tbody tr { border-top: 1px solid var(--dbi-evals-line); cursor: pointer; transition: background-color 140ms; animation: dbi-evals-rise 420ms var(--dbi-evals-ease) both; animation-delay: calc(var(--i) * 35ms); }
  .dbi-evals-runs tbody tr:hover { background: var(--dbi-evals-sunk); }
  .dbi-evals-runs tbody tr:focus-visible { outline-offset: -2px; border-radius: 0; }
  .dbi-evals-runs td.dbi-evals-num, .dbi-evals-runs th.dbi-evals-num { font-family: var(--dbi-evals-mono); font-size: 12px; white-space: nowrap; }
  .dbi-evals-runs .dbi-evals-vcell b { font: 650 12.5px var(--dbi-evals-mono); }
  .dbi-evals-runs .dbi-evals-vcell small, .dbi-evals-runs .dbi-evals-chg small { display: block; font-size: 11px; color: var(--dbi-evals-faint); }
  .dbi-evals-runs .dbi-evals-chg { max-width: 34ch; text-wrap: pretty; }
  .dbi-evals-tag { display: inline-block; font-size: 10.5px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; padding: 2px 7px; border-radius: 99px; background: var(--dbi-evals-sunk); color: var(--dbi-evals-muted); white-space: nowrap; }
