const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');

/* ---------- versions, suites, scores ----------
   A score is passes / cases. A cell is a regression or improvement only when a
   two-proportion z-test against the baseline clears 1.96 and the move exceeds 1 pt. */
const VERSIONS = [
  { v: 'v14', date: 'Aug 4', by: 'Hana Ito', note: 'Q3 baseline — system prompt split into policy blocks' },
  { v: 'v15', date: 'Aug 11', by: 'Hana Ito', note: 'Refund edge cases added to the few-shot set' },
  { v: 'v16', date: 'Aug 19', by: 'Omar Feld', note: 'JSON schema reminder placed before tool calls' },
  { v: 'v17', date: 'Aug 26', by: 'Omar Feld', note: 'Persona rules moved below the tool section' },
  { v: 'v18', date: 'Sep 2', by: 'Lise Brandt', note: 'Summary instructions shortened by 40%' },
  { v: 'v19', date: 'Sep 9', by: 'Lise Brandt', note: 'Summary guardrails restored; promoted to production' },
  { v: 'v20', date: 'Sep 16', by: 'Hana Ito', note: 'Citation format examples added' },
  { v: 'v21', date: 'Sep 23', by: 'Kofi Mensah', note: 'Context trimming keeps the last 6 turns' },
  { v: 'v22', date: 'Sep 30', by: 'Kofi Mensah', note: 'Retrieval preamble compressed (−310 tokens)' }
];
const PROD = 5;
const SUITES = [
  { id: 'refund-policy-qa', name: 'Refund policy QA', n: 240, d: 'Answers that must match the 2026 refund matrix, including partial refunds and store credit.',
    s: [86.2, 88.8, 88.3, 89.2, 88.8, 89.6, 90.0, 89.6, 90.4], off: 6 },
  { id: 'tool-call-json', name: 'Tool-call JSON validity', n: 500, d: 'Every tool call must parse against its JSON schema on the first attempt.',
    s: [91.4, 91.8, 97.2, 97.0, 97.4, 97.6, 97.8, 97.2, 97.6], off: 3, nx: [0, 0, 0, 0, 0, 0, -5.2, 0, 0] },
  { id: 'summary-faithfulness', name: 'Summary faithfulness', n: 320, d: 'Ticket summaries may not add facts that are absent from the conversation.',
