function scoresFor(model) {
  return SUITES.map(su => su.s.map((v, i) => {
    const raw = model === 'atlas' ? v : v - su.off + (su.nx ? su.nx[i] : 0);
    const passes = Math.round(Math.max(0, Math.min(100, raw)) * su.n / 100);
    return { passes, rate: passes / su.n };
  }));
}
const DATA = { atlas: scoresFor('atlas'), nimbus: scoresFor('nimbus') };
const TOTAL_CASES = SUITES.reduce((a, s) => a + s.n, 0);

function compare(a, b, n) {
  // b is the baseline; returns pp delta, z and a flag
  const d = (a.rate - b.rate) * 100;
  const se = Math.sqrt(a.rate * (1 - a.rate) / n + b.rate * (1 - b.rate) / n) * 100 || 1;
  const z = d / se;
  const flag = z <= -1.96 && d < -1 ? 'reg' : z >= 1.96 && d > 1 ? 'imp' : Math.abs(d) >= 2 ? 'watch' : '';
  return { d, z, flag, ci: 1.96 * Math.sqrt(a.rate * (1 - a.rate) / n) * 100 };
