const nf = new Intl.NumberFormat('en-US');
const baseIdx = c => st.base === 'prev' ? c - 1 : PROD;

function vt(fn) {
  if (!reduce && document.startViewTransition) {
    try { const t = document.startViewTransition(fn); t.ready.catch(() => {}); t.finished.catch(() => {}); return; } catch (e) { /* fall through */ }
  }
  fn();
}

function cellInfo(r, c) {
  const S = DATA[st.model], b = baseIdx(c);
  const cur = S[r][c];
  if (b < 0 || b === c) return { cur, cmp: null };
  return { cur, cmp: compare(cur, S[r][b], SUITES[r].n), base: S[r][b], b };
}

/* ---------- matrix ---------- */
const matrix = $('.dbi-evals-matrix');
function renderMatrix(animate) {
  matrix.style.setProperty('--cols', VERSIONS.length);
  let h = `<div class="dbi-evals-mrow dbi-evals-mhead" role="row"><div class="dbi-evals-rh" role="columnheader"><small>suite</small></div>` +
    VERSIONS.map((V, c) => `<button class="dbi-evals-vh" role="columnheader" data-col="${c}" aria-selected="${c === st.col}"${c === PROD ? ' data-prod' : ''} title="${esc(V.note)}">${V.v}<small>${V.date}</small></button>`).join('') + '</div>';
  SUITES.forEach((su, r) => {
    const sel = cellInfo(r, st.col);
    const moved = sel.cmp && sel.cmp.flag && sel.cmp.flag !== 'watch';
    h += `<div class="dbi-evals-mrow" role="row" data-r="${r}"${st.only && !moved ? ' data-out' : ''}><div class="dbi-evals-rh" role="rowheader"><b>${su.name}</b><small>${su.n} cases</small></div>`;
    VERSIONS.forEach((V, c) => {
      const { cur, cmp } = cellInfo(r, c);
      const s = Math.max(0, Math.min(100, (cur.rate * 100 - 62) / 36 * 100));
      const lbl = `${su.name}, ${V.v}: ${fmt1(cur.rate * 100)}%` + (cmp ? `, ${sgn(cmp.d)} points${cmp.flag === 'reg' ? ', significant regression' : cmp.flag === 'imp' ? ', significant improvement' : ''}` : '');
      h += `<div class="dbi-evals-c${c === st.col ? ' dbi-evals-col' : ''}" role="gridcell" tabindex="${r === st.row && c === st.col ? 0 : -1}" aria-selected="${r === st.row && c === st.col}" aria-label="${esc(lbl)}" data-r="${r}" data-c="${c}"${cmp && cmp.flag ? ` data-flag="${cmp.flag}"` : ''}${s > 58 ? ' data-dark' : ''} style="--s:${s.toFixed(1)};--i:${animate ? r + c : 0}">${fmt1(cur.rate * 100)}${cmp ? `<small>${sgn(cmp.d)}</small>` : ''}</div>`;
    });
    h += '</div>';
  });
  matrix.innerHTML = h;
  if (!animate) $$('.dbi-evals-c', matrix).forEach(c => { c.style.animation = 'none'; });
  matrix.setAttribute('aria-rowcount', SUITES.length + 1);
}

// keep the active cell inside the matrix scroller without scrolling the page
function reveal(el) {
  const sc = matrix.parentElement, a = el.offsetLeft, b = a + el.offsetWidth, pad = 150;
  if (a - pad < sc.scrollLeft) sc.scrollLeft = Math.max(0, a - pad);
  else if (b > sc.scrollLeft + sc.clientWidth) sc.scrollLeft = b - sc.clientWidth + 8;
}
function select(r, c, focus) {
  const prevCol = st.col;
