  if (prevCol !== c) { renderMatrix(false); renderSummary(); }
  $$('.dbi-evals-c', matrix).forEach(el => {
    const on = +el.dataset.r === r && +el.dataset.c === c;
    el.setAttribute('aria-selected', String(on)); el.tabIndex = on ? 0 : -1;
    el.classList.toggle('dbi-evals-col', +el.dataset.c === c);
