  const el = $(`.dbi-evals-c[data-r="${r}"][data-c="${c}"]`, matrix);
  if (el) { reveal(el); if (focus) el.focus({ preventScroll: true }); }
  renderDetail();
}

/* ---------- summary ---------- */
function totals(c) {
