  const rate = totals(c) * 100, brate = b >= 0 && b !== c ? totals(b) * 100 : null;
  const V = VERSIONS[c];
  const gate = reg ? `Blocked — ${reg} significant regression${reg > 1 ? 's' : ''}` : 'Clear to promote';
  const bl = b >= 0 && b !== c ? VERSIONS[b].v : '—';
  $('.dbi-evals-summary').innerHTML = `
    <div style="--i:0"><span class="dbi-evals-eyebrow">${V.v} pass rate</span><b>${fmt1(rate)}%</b><small>${nf.format(Math.round(rate / 100 * TOTAL_CASES))} of ${nf.format(TOTAL_CASES)} cases</small></div>
    <div style="--i:1"><span class="dbi-evals-eyebrow">vs ${bl}</span><b class="${brate == null ? '' : rate - brate >= 0 ? 'dbi-evals-pos' : 'dbi-evals-neg'}">${brate == null ? '—' : sgn(rate - brate) + ' pts'}</b><small>${brate == null ? 'no baseline' : fmt1(brate) + '% baseline'}</small></div>
    <div style="--i:2"><span class="dbi-evals-eyebrow">Regressions</span><b class="${reg ? 'dbi-evals-neg' : ''}">${reg}</b><small>${watch} more within noise</small></div>
    <div style="--i:3"><span class="dbi-evals-eyebrow">Improvements</span><b class="${imp ? 'dbi-evals-pos' : ''}">${imp}</b><small>of ${SUITES.length} suites</small></div>
    <div class="dbi-evals-gate" style="--i:4"${reg ? ' data-blocked' : ''}><span class="dbi-evals-eyebrow">Promotion gate · ${V.by}</span><b><i></i>${gate}</b><small>${esc(V.note)}</small></div>`;
}

/* ---------- detail ---------- */
const detail = $('.dbi-evals-detail');
let sparkGeo = null;
function renderDetail() {
