  VERSIONS.forEach((V, i) => { if (i % 2 === 0 || i === pts.length - 1) g += `<text class="dbi-evals-axis" x="${x(i)}" y="${h - 3}" text-anchor="middle">${V.v}</text>`; });
  const band = `M${pts.map((p, i) => `${x(i)},${y(p.hi)}`).join('L')}L${pts.map((p, i) => `${x(i)},${y(p.lo)}`).reverse().join('L')}Z`;
  g += `<path class="dbi-evals-band" d="${band}"/><path class="dbi-evals-sline" d="M${pts.map((p, i) => `${x(i)},${y(p.v)}`).join('L')}"/>`;
  pts.forEach((p, i) => {
    const b = st.base === 'prev' ? i - 1 : PROD;
    const f = b >= 0 && b !== i ? compare(S[i], S[b], n).flag : '';
    g += `<circle class="dbi-evals-pt" cx="${x(i)}" cy="${y(p.v)}" r="4"${f === 'reg' || f === 'imp' ? ` data-flag="${f}"` : ''}${i === st.col ? ' data-sel' : ''} data-i="${i}"/>`;
  });
