@keyframes dbi-trace-bar { from { clip-path: inset(0 100% 0 0 round 3px); } to { clip-path: inset(0 0 0 0 round 3px); } }
@keyframes dbi-trace-rise { from { opacity: 0; transform: translateY(6px); } }
@keyframes dbi-trace-in { from { opacity: 0; transform: translateX(12px); } }
@keyframes dbi-trace-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }

.dbi-trace {
  /* re-theme with these */
  --dbi-trace-bg: oklch(0.165 0.008 55);
  --dbi-trace-ink: oklch(0.93 0.015 75);
  --dbi-trace-accent: oklch(0.74 0.13 38);
  --dbi-trace-err: oklch(0.66 0.2 25);
