  --dbi-trace-k-agent: oklch(0.84 0.035 80);
  --dbi-trace-k-llm: oklch(0.72 0.14 38);
  --dbi-trace-k-retrieval: oklch(0.76 0.1 165);
  --dbi-trace-k-tool: oklch(0.83 0.12 95);
  --dbi-trace-k-guard: oklch(0.72 0.07 290);
  --dbi-trace-k-io: oklch(0.7 0.05 235);
  /* derived */
