  --dbi-trace-raise: color-mix(in oklch, var(--dbi-trace-bg), white 7%);
  --dbi-trace-deep: color-mix(in oklch, var(--dbi-trace-bg), black 25%);
  --dbi-trace-line: color-mix(in oklch, var(--dbi-trace-ink) 9%, transparent);
  --dbi-trace-line-2: color-mix(in oklch, var(--dbi-trace-ink) 17%, transparent);
  --dbi-trace-muted: color-mix(in oklch, var(--dbi-trace-ink) 58%, var(--dbi-trace-bg));
  --dbi-trace-faint: color-mix(in oklch, var(--dbi-trace-ink) 36%, var(--dbi-trace-bg));
  --dbi-trace-namew: 214px;
  --dbi-trace-durw: 74px;
  --dbi-trace-ease: cubic-bezier(0.2, 0.9, 0.25, 1);
  --dbi-trace-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbi-trace-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbi-trace-bg);
  color: var(--dbi-trace-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: dark;
  accent-color: var(--dbi-trace-accent);
  box-shadow: inset 0 0 0 1px var(--dbi-trace-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
