  & :focus-visible { outline: 2px solid var(--dbi-trace-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbi-trace-eyebrow { font: 600 10px/1.2 var(--dbi-trace-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbi-trace-muted); }

  .dbi-trace-app { display: grid; height: 100%; grid-template-columns: 226px minmax(0, 1fr) 256px; grid-template-areas: "list center drawer"; }

  /* ---------- trace list ---------- */
