  .dbi-trace-search input { width: 100%; height: 32px; padding: 0 10px 0 30px; border-radius: 8px; border: 0; background: var(--dbi-trace-panel); color: var(--dbi-trace-ink); font: 12px system-ui, sans-serif; box-shadow: inset 0 0 0 1px var(--dbi-trace-line); outline: none; transition: box-shadow 150ms; }
