  .dbi-trace-tr[aria-selected="true"] { background: var(--dbi-trace-raise); box-shadow: inset 0 0 0 1px var(--dbi-trace-line-2); }
  .dbi-trace-tr b { font: 600 12px var(--dbi-trace-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
