  .dbi-trace-status { display: inline-flex; align-items: center; gap: 6px; font: 600 10.5px var(--dbi-trace-mono); text-transform: uppercase; letter-spacing: 0.06em; color: var(--dbi-trace-k-retrieval); }
  .dbi-trace-status i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
