  .dbi-trace-cpbtn { height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dbi-trace-muted); box-shadow: inset 0 0 0 1px var(--dbi-trace-line-2); display: inline-flex; align-items: center; gap: 6px; transition: color 150ms, box-shadow 150ms, background-color 150ms; }
  .dbi-trace-cpbtn svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
