css:
@property --dbi-limits-g { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@keyframes dbi-limits-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbi-limits-ping { 0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--dbi-limits-ok) 70%, transparent); } 100% { box-shadow: 0 0 0 7px transparent; } }

.dbi-limits {
  /* re-theme with these */
  --dbi-limits-bg: oklch(0.165 0.014 165);
  --dbi-limits-ink: oklch(0.94 0.012 150);
  --dbi-limits-ok: oklch(0.78 0.14 152);
  --dbi-limits-thr: oklch(0.82 0.15 82);
  --dbi-limits-err: oklch(0.66 0.21 27);
  /* derived */
  --dbi-limits-panel: color-mix(in oklch, var(--dbi-limits-bg), white 3.5%);
  --dbi-limits-raise: color-mix(in oklch, var(--dbi-limits-bg), white 7%);
  --dbi-limits-deep: color-mix(in oklch, var(--dbi-limits-bg), black 28%);
  --dbi-limits-line: color-mix(in oklch, var(--dbi-limits-ink) 9%, transparent);
  --dbi-limits-line-2: color-mix(in oklch, var(--dbi-limits-ink) 17%, transparent);
  --dbi-limits-muted: color-mix(in oklch, var(--dbi-limits-ink) 58%, var(--dbi-limits-bg));
  --dbi-limits-faint: color-mix(in oklch, var(--dbi-limits-ink) 36%, var(--dbi-limits-bg));
  --dbi-limits-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbi-limits-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbi-limits-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbi-limits-bg);
  color: var(--dbi-limits-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: dark;
  accent-color: var(--dbi-limits-ok);
  box-shadow: inset 0 0 0 1px var(--dbi-limits-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbi-limits-ok); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbi-limits-eyebrow { font: 600 10px/1.2 var(--dbi-limits-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbi-limits-muted); }

  .dbi-limits-app { display: grid; height: 100%; grid-template-columns: 184px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }
  .dbi-limits-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 14px; border-right: 1px solid var(--dbi-limits-line); background: var(--dbi-limits-deep); }
  .dbi-limits-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbi-limits-brand svg { width: 30px; height: 30px; padding: 5px; border-radius: 8px; background: var(--dbi-limits-ok); fill: none; stroke: var(--dbi-limits-bg); stroke-width: 1.9; stroke-linejoin: round; stroke-linecap: round; }
  .dbi-limits-brand span { display: grid; line-height: 1.2; }
  .dbi-limits-brand b { font-weight: 700; }
  .dbi-limits-brand small { font-size: 11px; color: var(--dbi-limits-muted); }
  .dbi-limits-nav { display: grid; gap: 2px; }
  .dbi-limits-navbtn { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbi-limits-muted); font-weight: 560; transition: color 150ms, background-color 150ms; }
  .dbi-limits-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbi-limits-navbtn:hover { color: var(--dbi-limits-ink); background: color-mix(in oklch, var(--dbi-limits-ink) 5%, transparent); }
