const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

// ids and radio names must stay unique if the component is mounted twice
const uid = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => { el.id += '-' + uid; });
$$('[aria-controls], [aria-labelledby]').forEach(el => {
  ['aria-controls', 'aria-labelledby'].forEach(a => { if (el.hasAttribute(a)) el.setAttribute(a, el.getAttribute(a) + '-' + uid); });
});
$$('input[type="radio"]').forEach(el => { el.name += '-' + uid; });

/* ---------- models: prices per 1M tokens, p95 for a 500-token reply, quality by task ---------- */
const MODELS = [
  { id: 'atlas-large', lab: 'Atlas Labs', pin: 3.0, pout: 15.0, p95: 2.4, tps: 62, q: { support: 91, coding: 89, extract: 94, reason: 92 } },
  { id: 'atlas-mini', lab: 'Atlas Labs', pin: 0.4, pout: 1.6, p95: 0.9, tps: 148, q: { support: 84, coding: 76, extract: 90, reason: 74 } },
  { id: 'nimbus-pro', lab: 'Nimbus AI', pin: 1.25, pout: 5.0, p95: 1.7, tps: 88, q: { support: 89, coding: 85, extract: 92, reason: 87 } },
  { id: 'nimbus-mini', lab: 'Nimbus AI', pin: 0.3, pout: 1.2, p95: 0.7, tps: 170, q: { support: 82, coding: 71, extract: 88, reason: 69 } },
  { id: 'cirrus-code-2', lab: 'Cirrus', pin: 1.1, pout: 4.4, p95: 1.5, tps: 95, q: { support: 78, coding: 92, extract: 83, reason: 84 } },
  { id: 'halcyon-xl', lab: 'Halcyon Research', pin: 5.0, pout: 20.0, p95: 3.6, tps: 41, q: { support: 90, coding: 90, extract: 92, reason: 95 } },
  { id: 'ember-small', lab: 'Emberline', pin: 0.1, pout: 0.4, p95: 0.5, tps: 210, q: { support: 72, coding: 58, extract: 81, reason: 55 } },
  { id: 'ridge-70b', lab: 'self-hosted', pin: 0.55, pout: 0.55, p95: 1.9, tps: 54, q: { support: 81, coding: 77, extract: 85, reason: 76 } },
  { id: 'quill-3', lab: 'Quill Systems', pin: 2.0, pout: 8.0, p95: 2.0, tps: 70, q: { support: 88, coding: 80, extract: 89, reason: 83 } },
  { id: 'tern-8b', lab: 'Tern Collective', pin: 0.06, pout: 0.24, p95: 0.4, tps: 260, q: { support: 64, coding: 49, extract: 74, reason: 44 } }
];
const TASKS = { support: 'Support replies', coding: 'Code edits', extract: 'Field extraction', reason: 'Multi-step reasoning' };
MODELS.forEach(m => {
  m.cost = (3 * m.pin + m.pout) / 4;   // blended at 3:1 input:output
  m.q.all = (m.q.support + m.q.coding + m.q.extract + m.q.reason) / 4;
});
const DEF = { q: 60, c: 25, l: 15 };
const st = { task: 'all', w: { ...DEF }, sort: 'score', tab: 'board', a: 'atlas-large', b: 'nimbus-pro' };
const fmtQ = v => st.task === 'all' ? v.toFixed(1) : v.toFixed(0);
const fmtC = v => '$' + (v < 1 ? v.toFixed(v < 0.2 ? 3 : 2) : v.toFixed(2));

function scored() {
  const qs = MODELS.map(m => m.q[st.task]), cs = MODELS.map(m => Math.log(m.cost)), ls = MODELS.map(m => m.p95);
  const [q0, q1] = [Math.min(...qs), Math.max(...qs)], [c0, c1] = [Math.min(...cs), Math.max(...cs)], [l0, l1] = [Math.min(...ls), Math.max(...ls)];
  let { q: wq, c: wc, l: wl } = st.w;
  if (wq + wc + wl === 0) wq = wc = wl = 1;
  return MODELS.map(m => {
    const qn = (m.q[st.task] - q0) / (q1 - q0), cn = (c1 - Math.log(m.cost)) / (c1 - c0), ln = (l1 - m.p95) / (l1 - l0);
    return { m, q: m.q[st.task], score: 100 * (wq * qn + wc * cn + wl * ln) / (wq + wc + wl) };
  });
}
function frontier(list) {
  const pts = list.slice().sort((a, b) => a.m.cost - b.m.cost);
  const out = []; let best = -Infinity;
  pts.forEach(p => { if (p.q > best) { out.push(p); best = p.q; } });
  return out;
}

/* ---------- ranking with FLIP ---------- */
const rank = $('.dbi-arena-rank');
const rowsById = new Map();
function buildRows() {
  rank.innerHTML = MODELS.map((m, i) => `<li class="dbi-arena-row" data-id="${m.id}" style="--i:${i}">
    <span class="dbi-arena-rk"></span>
    <div class="dbi-arena-mc"><b>${m.id}<small>${m.lab}</small></b><div class="dbi-arena-sb"><span><i></i></span><em></em></div></div>
    <span class="dbi-arena-num" data-c="q"></span><span class="dbi-arena-num" data-c="c"></span><span class="dbi-arena-num" data-c="l"></span></li>`).join('');
  $$('.dbi-arena-row', rank).forEach(li => rowsById.set(li.dataset.id, li));
  rank.dataset.intro = '';
  setTimeout(() => { if (!root.isConnected) return; delete rank.dataset.intro; $$('.dbi-arena-row', rank).forEach(li => { li.style.animation = 'none'; $('.dbi-arena-sb i', li).style.animation = 'none'; }); }, 1400);
}
function update(animate) {
  const list = scored();
  const by = { score: (a, b) => b.score - a.score, q: (a, b) => b.q - a.q, c: (a, b) => a.m.cost - b.m.cost, l: (a, b) => a.m.p95 - b.m.p95 };
  list.sort(by[st.sort]);
  const first = new Map();
  if (animate && !reduce) rowsById.forEach((li, id) => first.set(id, li.getBoundingClientRect().top));
  list.forEach((s, i) => {
    const li = rowsById.get(s.m.id);
    $('.dbi-arena-rk', li).textContent = i + 1;
    $('.dbi-arena-sb i', li).style.setProperty('--s', s.score.toFixed(1));
    $('.dbi-arena-sb em', li).textContent = s.score.toFixed(0);
    $('[data-c="q"]', li).textContent = fmtQ(s.q);
    $('[data-c="c"]', li).textContent = fmtC(s.m.cost);
    $('[data-c="l"]', li).innerHTML = s.m.p95.toFixed(1) + '<small>s</small>';
    li.setAttribute('aria-label', `${i + 1}. ${s.m.id}, score ${s.score.toFixed(0)}, quality ${fmtQ(s.q)}, ${fmtC(s.m.cost)} per million tokens, p95 ${s.m.p95} seconds`);
    if (rank.children[i] !== li) rank.insertBefore(li, rank.children[i]);
  });
  if (first.size) rowsById.forEach((li, id) => {
    const dy = first.get(id) - li.getBoundingClientRect().top;
    if (Math.abs(dy) > 0.5) li.animate([{ transform: `translateY(${dy}px)` }, { transform: 'translateY(0)' }], { duration: 560, easing: 'cubic-bezier(0.2, 0.85, 0.25, 1)' });
  });
  drawScatter(list, animate);
  verdict(list);
  if (st.tab === 'h2h') duel();
}

/* ---------- scatter ---------- */
const scat = $('.dbi-arena-scat'), ssvg = $('svg', scat), tip = $('.dbi-arena-tip', scat);
let built = false, sgeo = null;
const XD = [0.08, 12], YD = [40, 100];
function drawScatter(list, animate) {
  const w = scat.clientWidth, h = scat.clientHeight;
  if (!w || !h) return;
  const L = 40, R = 16, T = 12, B = 34, iw = w - L - R, ih = h - T - B;
  const x = c => L + Math.log(c / XD[0]) / Math.log(XD[1] / XD[0]) * iw;
  const y = q => T + ih - (q - YD[0]) / (YD[1] - YD[0]) * ih;
  const fr = frontier(list), frIds = new Set(fr.map(p => p.m.id));
  sgeo = { x, y };
  if (!built || ssvg.dataset.w !== String(w) || ssvg.dataset.h !== String(h)) {
    let g = '';
    [40, 50, 60, 70, 80, 90, 100].forEach(v => { g += `<line class="dbi-arena-gl" x1="${L}" x2="${w - R}" y1="${y(v)}" y2="${y(v)}"/><text class="dbi-arena-ax" x="${L - 7}" y="${y(v)}" dy="0.33em" text-anchor="end">${v}</text>`; });
    [0.1, 0.3, 1, 3, 10].forEach(v => { g += `<line class="dbi-arena-gl" x1="${x(v)}" x2="${x(v)}" y1="${T}" y2="${T + ih}"/><text class="dbi-arena-ax" x="${x(v)}" y="${T + ih + 15}" text-anchor="middle">$${v}</text>`; });
    g += `<text class="dbi-arena-axt" x="${L + iw}" y="${h - 3}" text-anchor="end">blended $ per 1M tokens, log</text><text class="dbi-arena-axt" x="${L}" y="${T - 2}">quality</text>`;
    g += '<path class="dbi-arena-front"/>';
    g += MODELS.map((m, i) => `<g class="dbi-arena-pt" data-id="${m.id}" style="--i:${i}"><circle r="${(3.5 + m.tps / 40).toFixed(1)}"/><text></text></g>`).join('');
    ssvg.innerHTML = g;
    ssvg.setAttribute('viewBox', `0 0 ${w} ${h}`);
    ssvg.dataset.w = w; ssvg.dataset.h = h;
    built = true;
  }
  // greedy label placement: right, then left, then above, then below
  const rad = m => 3.5 + m.tps / 40;
  const boxes = list.map(s => { const px = x(s.m.cost), py = y(s.q), r = rad(s.m); return [px - r, py - r, px + r, py + r]; });
  const placed = list.slice().sort((a, b) => b.q - a.q).map(s => {
    const px = x(s.m.cost), py = y(s.q), r = rad(s.m), tw = s.m.id.length * 6.4 + 4;
    const cands = [[r + 5, 4, 'start'], [-r - 5, 4, 'end'], [0, -r - 6, 'middle'], [0, r + 13, 'middle']];
    let pick = cands[0];
    for (const c of cands) {
      const bx = c[2] === 'start' ? px + c[0] : c[2] === 'end' ? px + c[0] - tw : px - tw / 2, by = py + c[1] - 10;
      const box = [bx, by, bx + tw, by + 13];
      if (box[2] > w - 2 || box[0] < L) continue;
      if (!boxes.some(o => box[0] < o[2] && box[2] > o[0] && box[1] < o[3] && box[3] > o[1])) { pick = c; boxes.push(box); break; }
    }
    return { s, px, py, pick };
  });
  placed.forEach(({ s, px, py, pick }) => {
    const g = $(`.dbi-arena-pt[data-id="${s.m.id}"]`, ssvg), t = $('text', g);
    g.style.transform = `translate(${px.toFixed(1)}px, ${py.toFixed(1)}px)`;
    g.toggleAttribute('data-front', frIds.has(s.m.id));
    t.textContent = s.m.id; t.setAttribute('x', pick[0]); t.setAttribute('y', pick[1]); t.setAttribute('text-anchor', pick[2]);
  });
  const d = 'M' + fr.map(p => `${x(p.m.cost).toFixed(1)},${y(p.q).toFixed(1)}`).join('L');
  const front = $('.dbi-arena-front', ssvg);
  front.setAttribute('d', d);
  front.style.setProperty('--len', Math.ceil(front.getTotalLength()));
  if (animate && !reduce) { front.style.animation = 'none'; void front.getBoundingClientRect(); front.style.animation = ''; }
}
function showTip(id) {
  const s = scored().find(v => v.m.id === id);
  $$('.dbi-arena-pt', ssvg).forEach(g => g.toggleAttribute('data-hot', g.dataset.id === id));
  rowsById.forEach((li, k) => li.toggleAttribute('data-hot', k === id));
  if (!s) { tip.classList.remove('dbi-arena-on'); return; }
  const m = s.m, px = sgeo.x(m.cost), py = sgeo.y(s.q);
  tip.innerHTML = `<header>${m.id}</header><div><span>${st.task === 'all' ? 'quality, all tasks' : TASKS[st.task]}</span>${fmtQ(s.q)}</div><div><span>in / out per 1M</span>$${m.pin.toFixed(2)} / $${m.pout.toFixed(2)}</div><div><span>blended</span>${fmtC(m.cost)}</div><div><span>p95 · throughput</span>${m.p95.toFixed(1)} s · ${m.tps} tok/s</div><div><span>score</span>${s.score.toFixed(1)}</div>`;
  const tw = tip.offsetWidth, th = tip.offsetHeight, W = scat.clientWidth;
  tip.style.left = Math.max(0, Math.min(W - tw, px + 14 + tw > W ? px - tw - 14 : px + 14)) + 'px';
  tip.style.top = Math.max(0, py - th - 10) + 'px';
  tip.classList.add('dbi-arena-on');
}
function clearTip() {
  tip.classList.remove('dbi-arena-on');
  $$('.dbi-arena-pt[data-hot]', ssvg).forEach(g => g.removeAttribute('data-hot'));
  rowsById.forEach(li => li.removeAttribute('data-hot'));
}
function verdict(list) {
  const top = list.slice().sort((a, b) => b.score - a.score)[0], best = list.slice().sort((a, b) => b.q - a.q)[0];
  const el = $('.dbi-arena-verdict');
  if (top.m.id === best.m.id) {
    const near = frontier(list).filter(p => p.q >= best.q - 5 && p.m.id !== best.m.id)[0];
    el.innerHTML = `At these weights <b>${top.m.id}</b> leads outright${near ? `; <b>${near.m.id}</b> is within 5 points for ${Math.round(near.m.cost / best.m.cost * 100)}% of the price.` : '.'}`;
  } else {
    el.innerHTML = `At these weights <b>${top.m.id}</b> leads: ${Math.round(top.q / best.q * 100)}% of <b>${best.m.id}</b>’s quality at ${Math.max(1, Math.round(top.m.cost / best.m.cost * 100))}% of its cost.`;
  }
}

/* ---------- head-to-head ---------- */
function duel() {
  const A = MODELS.find(m => m.id === st.a), B = MODELS.find(m => m.id === st.b);
  const rows = Object.keys(TASKS).map(k => ({ label: TASKS[k], a: A.q[k], b: B.q[k], hi: true, fmt: v => v.toFixed(0), floor: 40, scale: 100 }));
  rows.push({ label: 'Blended $ / 1M', a: A.cost, b: B.cost, hi: false, fmt: fmtC });
  rows.push({ label: 'p95 latency', a: A.p95, b: B.p95, hi: false, fmt: v => v.toFixed(1) + ' s' });
  rows.push({ label: 'Throughput', a: A.tps, b: B.tps, hi: true, fmt: v => v + ' tok/s' });
  const html = rows.map((r, i) => {
    const f = r.floor || 0, mx = r.scale || Math.max(r.a, r.b), wa = (r.a - f) / (mx - f) * 100, wb = (r.b - f) / (mx - f) * 100;
    const aw = r.a === r.b ? false : (r.hi ? r.a > r.b : r.a < r.b), bw = r.a === r.b ? false : !aw;
    return `<div class="dbi-arena-drow" style="--i:${i}"><span class="dbi-arena-half"${aw ? ' data-win' : ''}><i style="--v:${wa.toFixed(1)}"></i>${r.fmt(r.a)}</span><span>${r.label}</span><span class="dbi-arena-half"${bw ? ' data-win' : ''}><i style="--v:${wb.toFixed(1)}"></i>${r.fmt(r.b)}</span></div>`;
  }).join('');
  const tasks = Object.keys(TASKS), winsA = tasks.filter(k => A.q[k] > B.q[k]).length, ties = tasks.filter(k => A.q[k] === B.q[k]).length;
  const avg = tasks.reduce((s, k) => s + (A.q[k] - B.q[k]), 0) / tasks.length;
  const ratio = A.cost / B.cost;
  const lead = winsA >= tasks.length - winsA - ties ? [A, winsA, avg] : [B, tasks.length - winsA - ties, -avg];
  const sum = A.id === B.id ? 'Pick two different models to compare.' :
    `<b>${lead[0].id}</b> wins ${lead[1]} of ${tasks.length} tasks${ties ? ` (${ties} tied)` : ''}, by ${Math.abs(lead[2]).toFixed(1)} points on average. <b>${A.id}</b> costs ${ratio >= 1 ? ratio.toFixed(1) + '×' : (1 / ratio).toFixed(1) + '× less than'} ${ratio >= 1 ? 'as much as ' : ''}<b>${B.id}</b> per token.`;
  $('.dbi-arena-duel').innerHTML = `<div class="dbi-arena-dhead"><span>${A.id}</span><span>vs</span><span>${B.id}</span></div>${html}<p class="dbi-arena-sum">${sum}</p>`;
}
const selA = $('[data-pick="a"]'), selB = $('[data-pick="b"]');
[selA, selB].forEach(sel => { sel.innerHTML = MODELS.map(m => `<option value="${m.id}">${m.id}</option>`).join(''); });
selA.value = st.a; selB.value = st.b;
selA.addEventListener('change', () => { st.a = selA.value; duel(); });
selB.addEventListener('change', () => { st.b = selB.value; duel(); });
$('.dbi-arena-swap').addEventListener('click', () => { [st.a, st.b] = [st.b, st.a]; selA.value = st.a; selB.value = st.b; duel(); });

/* ---------- controls ---------- */
function setMix() {
  const { q, c, l } = st.w;
  $('.dbi-arena-mix [data-m="q"]').style.setProperty('--f', q || 0.0001);
  $('.dbi-arena-mix [data-m="c"]').style.setProperty('--f', c || 0.0001);
  $('.dbi-arena-mix [data-m="l"]').style.setProperty('--f', l || 0.0001);
}
$$('[data-w]').forEach(inp => inp.addEventListener('input', () => {
  st.w[inp.dataset.w] = +inp.value;
  $(`[data-o="${inp.dataset.w}"]`).textContent = inp.value;
  setMix(); update(true);
}));
$('.dbi-arena-reset').addEventListener('click', () => {
  st.w = { ...DEF };
  $$('[data-w]').forEach(inp => { inp.value = st.w[inp.dataset.w]; $(`[data-o="${inp.dataset.w}"]`).textContent = inp.value; });
  setMix(); update(true);
});
$('.dbi-arena-tasks').addEventListener('change', e => { if (e.target.name.indexOf('dbi-arena-task') === 0) { st.task = e.target.value; update(true); } });
$('.dbi-arena-rhead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  st.sort = b.dataset.sort;
  $$('[data-sort]').forEach(x => x.setAttribute('aria-pressed', String(x === b)));
  update(true);
});
rank.addEventListener('pointerover', e => { const li = e.target.closest('.dbi-arena-row'); if (li) showTip(li.dataset.id); });
rank.addEventListener('pointerleave', clearTip);
ssvg.addEventListener('pointerover', e => { const g = e.target.closest('.dbi-arena-pt'); if (g) showTip(g.dataset.id); });
ssvg.addEventListener('pointerleave', clearTip);

const tabs = $$('[role="tab"]');
function setTab(t, focus) {
  if (t === st.tab) return;
  const apply = () => {
    st.tab = t;
    tabs.forEach(b => { const on = b.dataset.tab === t; b.setAttribute('aria-selected', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
    $('.dbi-arena-board').hidden = t !== 'board'; $('.dbi-arena-h2h').hidden = t !== 'h2h';
    if (t === 'h2h') duel(); else { built = false; update(false); }
  };
  if (!reduce && document.startViewTransition) { try { const v = document.startViewTransition(apply); v.ready.catch(() => {}); v.finished.catch(() => {}); return; } catch (err) { /* fall through */ } }
  apply();
}
$('.dbi-arena-tabs').addEventListener('click', e => { const b = e.target.closest('[role="tab"]'); if (b) setTab(b.dataset.tab); });
$('.dbi-arena-tabs').addEventListener('keydown', e => {
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
  e.preventDefault();
  const i = tabs.findIndex(b => b.dataset.tab === st.tab);
  setTab(tabs[(i + (e.key === 'ArrowLeft' ? -1 : 1) + tabs.length) % tabs.length].dataset.tab, true);
});
const wt = $('.dbi-arena-wtoggle');
wt.addEventListener('click', () => wt.setAttribute('aria-expanded', String(wt.getAttribute('aria-expanded') !== 'true')));
root.addEventListener('keydown', e => { if (e.key === 'Escape' && wt.getAttribute('aria-expanded') === 'true') { wt.setAttribute('aria-expanded', 'false'); wt.focus(); } });
root.addEventListener('pointerdown', e => { if (wt.getAttribute('aria-expanded') === 'true' && !e.target.closest('.dbi-arena-controls, .dbi-arena-wtoggle')) wt.setAttribute('aria-expanded', 'false'); });

let lastW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = scat.clientWidth;
  if (w && w !== lastW) { lastW = w; built = false; drawScatter(scored(), false); }
});
ro.observe(scat);

buildRows();
setMix();
update(false);
lastW = scat.clientWidth;

css:
@keyframes dbi-rag-grow { from { transform: scaleY(0); } }
@keyframes dbi-rag-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbi-rag-fade { from { opacity: 0; } }
@keyframes dbi-rag-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }

.dbi-rag {
  /* re-theme with these */
  --dbi-rag-paper: oklch(0.968 0.013 128);
  --dbi-rag-ink: oklch(0.27 0.04 160);
  --dbi-rag-rel: oklch(0.53 0.11 158);
  --dbi-rag-irr: oklch(0.69 0.11 52);
  /* derived */
  --dbi-rag-card: color-mix(in oklch, var(--dbi-rag-paper), white 62%);
  --dbi-rag-sunk: color-mix(in oklch, var(--dbi-rag-paper), var(--dbi-rag-ink) 5%);
  --dbi-rag-line: color-mix(in oklch, var(--dbi-rag-ink) 11%, transparent);
  --dbi-rag-line-2: color-mix(in oklch, var(--dbi-rag-ink) 22%, transparent);
  --dbi-rag-muted: color-mix(in oklch, var(--dbi-rag-ink) 62%, var(--dbi-rag-paper));
  --dbi-rag-faint: color-mix(in oklch, var(--dbi-rag-ink) 42%, var(--dbi-rag-paper));
  --dbi-rag-tint: color-mix(in oklch, var(--dbi-rag-rel) 11%, var(--dbi-rag-card));
  --dbi-rag-miss: color-mix(in oklch, var(--dbi-rag-irr), oklch(0.55 0.2 28) 60%);
  --dbi-rag-ease: cubic-bezier(0.25, 1, 0.35, 1);
  --dbi-rag-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbi-rag-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbi-rag-paper);
  color: var(--dbi-rag-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbi-rag-rel);
  box-shadow: inset 0 0 0 1px var(--dbi-rag-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbi-rag-rel); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { list-style: none; margin: 0; padding: 0; }
  & fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbi-rag-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbi-rag-muted); }

  .dbi-rag-app { display: grid; height: 100%; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }
