const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const nf = new Intl.NumberFormat('en-US');
const uid = Math.random().toString(36).slice(2, 7);
$$('input[type="radio"]').forEach(el => { el.name += '-' + uid; });

/* ---------- graded eval set: each query has a gold document and answer ---------- */
const SOURCES = { 'help-center': 'Help center', manuals: 'Product manuals', warranty: 'Warranty & returns', forum: 'Community forum', release: 'Release notes' };
const Q = [
  ['How do I reset the soil moisture sensor?', 'manuals', 'Moisture Sensor S2 · Troubleshooting', 'Hold the pairing button for 8 seconds until the ring blinks amber, then add the sensor again in the app.', 0],
