  ['Do you ship live plants to Alaska?', 'help-center', 'Shipping · Live plants', 'Live plants ship to Alaska and Hawaii from April to June only, by 2-day air.', 0],
  ['What changed in hub firmware 3.2?', 'release', 'Hub firmware 3.2 release notes', 'Firmware 3.2 adds frost alerts, fixes the duplicate-zone bug and cuts standby power by 18%.', 0],
  ['How do I winterize the rain barrel pump?', 'manuals', 'Rain Barrel Pump P1 · Storage', 'Drain the pump, run it dry for 5 seconds, then store it indoors above 4 °C.', 0],
  ['Can I use the 40 V battery in the 20 V trimmer?', 'help-center', 'Batteries · Compatibility', '40 V packs fit only 40 V tools; the 20 V trimmer needs a 20 V pack.', 0],
  ['How long do refunds to store credit take?', 'warranty', 'Refunds · Timing', 'Refunds to store credit post instantly; card refunds take 3–5 business days.', 0],
  ['Grow light timer keeps resetting to 12 hours', 'forum', 'Thread: GL-30 timer resets', 'Firmware 1.4 fixed the reset; update it from the device page in the app.', 1],
  ['Best spacing for tomatoes in the 4×8 raised bed', 'help-center', 'Raised beds · Planting guides', 'Plant indeterminate tomatoes 60 cm apart, which fits six plants in a 4×8 bed.', 0],
